DROP TABLE IF EXISTS `eb_community_notes`;
CREATE TABLE `eb_community_notes`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '标题',
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '笔记类型：1-图文，2-视频',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '封面',
  `image` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `video` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '视频链接',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '笔记正文',
  `category_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '社区分类ID',
  `topic_ids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '话题ID,英文逗号拼接',
  `uid` int NOT NULL DEFAULT 0 COMMENT '用户ID',
  `star` tinyint(1) NULL DEFAULT 1 COMMENT '星级排序:1-5',
  `audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态:0-待审核，1-审核通过，2-审核失败，3-平台关闭',
  `refusal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拒绝理由',
  `like_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '点赞数',
  `reply_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论数',
  `share_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '分享数',
  `views` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '浏览量',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `reply_status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否开启评论，1-开启，2-关闭，3-平台关闭',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除，0-未删除，1-删除',
  `operate_time` timestamp NULL DEFAULT NULL COMMENT '操作时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_uid`(`uid` ASC) USING BTREE,
  INDEX `idx_front`(`type` ASC, `audit_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社区笔记表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_community_notes
-- ----------------------------

-- ----------------------------
-- Table structure for eb_community_notes_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_community_notes_product`;
CREATE TABLE `eb_community_notes_product`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `note_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '笔记ID',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `is_pay` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否购买：0-未购买，1-已购买',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_note_id`(`note_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社区笔记商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_community_notes_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_community_notes_relation
-- ----------------------------
DROP TABLE IF EXISTS `eb_community_notes_relation`;
CREATE TABLE `eb_community_notes_relation`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `note_id` int UNSIGNED NOT NULL COMMENT '笔记ID',
  `author_id` int UNSIGNED NOT NULL COMMENT '笔记作者ID',
  `uid` int UNSIGNED NOT NULL COMMENT '用户ID',
  `type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'like' COMMENT '关联类型(收藏(collect）、点赞(like))',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_data`(`note_id` ASC, `uid` ASC) USING BTREE,
  INDEX `idx_author_id`(`author_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社区笔记关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_community_notes_relation
-- ----------------------------

-- ----------------------------
-- Table structure for eb_community_reply
-- ----------------------------
DROP TABLE IF EXISTS `eb_community_reply`;
CREATE TABLE `eb_community_reply`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '评论类型：1-评论，2-回复',
  `uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发言用户ID',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '内容',
  `parent_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级评论ID',
  `parent_uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '一级用户ID',
  `review_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原评论ID',
  `review_uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '原评论用户ID',
  `count_start` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '点赞数',
  `count_reply` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '评论数',
  `audit_status` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态:0-待审核，1-审核通过，2-审核失败',
  `refusal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `note_id` int NOT NULL DEFAULT 0 COMMENT '笔记id',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除，0-未删除，1-删除',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_uid`(`uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社区评论表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_community_reply
-- ----------------------------

-- ----------------------------
-- Table structure for eb_community_reply_like
-- ----------------------------
DROP TABLE IF EXISTS `eb_community_reply_like`;
CREATE TABLE `eb_community_reply_like`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `note_id` int UNSIGNED NOT NULL COMMENT '笔记ID',
  `reply_id` int UNSIGNED NOT NULL COMMENT '评论ID',
  `uid` int UNSIGNED NOT NULL COMMENT '用户ID',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_data`(`note_id` ASC, `uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社区评论点赞表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_community_reply_like
-- ----------------------------

-- ----------------------------
-- Table structure for eb_community_topic
-- ----------------------------
DROP TABLE IF EXISTS `eb_community_topic`;
CREATE TABLE `eb_community_topic`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '话题名称',
  `is_hot` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐：1-推荐，0-不推荐',
  `count_use` int UNSIGNED NULL DEFAULT 0 COMMENT '使用次数',
  `count_view` int UNSIGNED NULL DEFAULT 0 COMMENT '浏览量',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除，0-未删除，1-删除',
  `create_type` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '创建类型：1-系统创建，2-用户创建',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '社区话题表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_community_topic
-- ----------------------------

-- ----------------------------
-- Table structure for eb_coupon
-- ----------------------------
DROP TABLE IF EXISTS `eb_coupon`;
CREATE TABLE `eb_coupon`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '优惠券表ID',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `publisher` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '发行方，1-平台，2-商户',
  `category` tinyint NOT NULL DEFAULT 1 COMMENT '类别 1-商家券, 2-商品券, 3-通用券，4-品类券，5-品牌券，6-跨店券',
  `receive_type` tinyint NOT NULL DEFAULT 1 COMMENT '领取类型 1-手动领取,2-商品赠送券,3-平台活动发放',
  `coupon_type` tinyint NOT NULL DEFAULT 1 COMMENT '优惠券类型 1-满减券,2-折扣券',
  `money` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠金额',
  `discount` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '折扣',
  `min_price` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最低消费，0代表不限制',
  `is_limited` tinyint(1) NULL DEFAULT 0 COMMENT '是否限量, 默认0 不限量， 1限量',
  `total` int NOT NULL DEFAULT 0 COMMENT '发放总数',
  `last_total` int NOT NULL DEFAULT 0 COMMENT '剩余数量',
  `is_time_receive` tinyint(1) NULL DEFAULT 0 COMMENT '领取是否限时, 默认0-不限时，1-限时',
  `receive_start_time` timestamp NULL DEFAULT NULL COMMENT '可领取开始时间',
  `receive_end_time` timestamp NULL DEFAULT NULL COMMENT '可领取结束时间',
  `is_fixed_time` tinyint(1) NULL DEFAULT 0 COMMENT '是否固定使用时间, 默认0-否，1-使用固定时间',
  `use_start_time` timestamp NULL DEFAULT NULL COMMENT '可使用时间范围 开始时间',
  `use_end_time` timestamp NULL DEFAULT NULL COMMENT '可使用时间范围 结束时间',
  `day` int NULL DEFAULT 0 COMMENT '天数',
  `sort` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序',
  `status` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '状态（0：关闭，1：开启）',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 状态（0：否，1：是）',
  `linked_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联数据',
  `is_repeated` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否可重复领取',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `publisher`(`publisher` ASC) USING BTREE,
  INDEX `is_del`(`is_del` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_coupon
-- ----------------------------

-- ----------------------------
-- Table structure for eb_coupon_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_coupon_product`;
CREATE TABLE `eb_coupon_product`  (
  `cid` int NOT NULL COMMENT '优惠券id',
  `pid` int NOT NULL COMMENT '商品id',
  PRIMARY KEY (`cid`, `pid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '优惠券商品关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_coupon_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_coupon_user
-- ----------------------------
DROP TABLE IF EXISTS `eb_coupon_user`;
CREATE TABLE `eb_coupon_user`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `coupon_id` int NOT NULL COMMENT '优惠券id',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '店铺id，平台为0',
  `uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `publisher` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '发行方，1-平台，2-商户',
  `category` tinyint NOT NULL DEFAULT 1 COMMENT '类别 1-商家券, 2-商品券, 3-通用拳，4-品类券，5-品牌券，6-跨店券',
  `receive_type` tinyint NOT NULL DEFAULT 1 COMMENT '领取类型 1-手动领取,2-商品赠送券,3-平台活动发放',
  `coupon_type` tinyint NOT NULL DEFAULT 1 COMMENT '优惠券类型 1-满减券,2-折扣券',
  `money` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠金额',
  `discount` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '折扣',
  `min_price` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '最低消费，0代表不限制',
  `start_time` timestamp NULL DEFAULT NULL COMMENT '开始使用时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '过期时间',
  `use_time` timestamp NULL DEFAULT NULL COMMENT '使用时间',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态（0：未使用，1：已使用, 2:已失效）',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE,
  INDEX `status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户优惠券表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_coupon_user
-- ----------------------------

-- ----------------------------
-- Table structure for eb_exception_log
-- ----------------------------
DROP TABLE IF EXISTS `eb_exception_log`;
CREATE TABLE `eb_exception_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '异常日志ID',
  `exp_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常的url',
  `exp_params` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '异常的参数',
  `exp_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常的类型',
  `exp_controller` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常的类名',
  `exp_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常的方法名',
  `exp_detail` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '异常详细信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '异常信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_exception_log
-- ----------------------------

-- ----------------------------
-- Table structure for eb_express
-- ----------------------------
DROP TABLE IF EXISTS `eb_express`;
CREATE TABLE `eb_express`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '快递公司id',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递公司简称',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递公司全称',
  `partner_id` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要月结账号',
  `partner_key` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要月结密码',
  `net` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要取件网店',
  `account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `net_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '网点名称',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `is_show` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否显示',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否可用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `code`(`code` ASC) USING BTREE,
  INDEX `is_show`(`is_show` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1102 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '快递公司表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_express
-- ----------------------------

-- ----------------------------
-- Table structure for eb_group_buy_activity
-- ----------------------------
DROP TABLE IF EXISTS `eb_group_buy_activity`;
CREATE TABLE `eb_group_buy_activity`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `group_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拼团活动名称',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `valid_hour` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '成团有效期 小时数',
  `buy_count` int NOT NULL DEFAULT 0 COMMENT '成团总人数 - 真团',
  `all_quota` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买上限',
  `onc_quota` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '单次购买数量',
  `group_status` int NOT NULL DEFAULT 0 COMMENT '控制状态 0=初始化 1=已拒绝 2=已撤销 3=待审核 4=已通过',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户ID',
  `mer_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户名称',
  `product_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '参与商品数量',
  `show_group` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '凑团 0不可见，1可见',
  `ficti_status` int NOT NULL DEFAULT 0 COMMENT '虚拟成团 假团 0关闭 1开启',
  `is_del` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '删除标记 0=未删除 1=已删除',
  `total_activity_begin` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计 - 开团数',
  `total_activity_done` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计 - 成团数',
  `total_order_begin` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计 - 参团订单数',
  `total_order_done` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '统计 - 成团订单数',
  `refusal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核拒绝理由',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `activity_status` int NOT NULL DEFAULT 1 COMMENT '活动状态 0关闭 1开启',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拼团活动表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_group_buy_activity
-- ----------------------------

-- ----------------------------
-- Table structure for eb_group_buy_activity_sku
-- ----------------------------
DROP TABLE IF EXISTS `eb_group_buy_activity_sku`;
CREATE TABLE `eb_group_buy_activity_sku`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `group_activity_id` int UNSIGNED NOT NULL COMMENT '拼团活动id',
  `product_id` int UNSIGNED NOT NULL COMMENT '拼团基础商品id',
  `active_price` decimal(10, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '拼团活动价',
  `quota_show` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '拼团限购数量 - 显示用',
  `quota` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '拼团剩余数量 - 随减',
  `sku_id` int NOT NULL COMMENT 'sku id',
  `group_status` int NOT NULL DEFAULT 0 COMMENT '控制状态 0=初始化 1=已拒绝 2=已撤销 3=待审核 4=已通过',
  `activity_status` int NOT NULL DEFAULT 0 COMMENT '活动状态 0关闭 1开启',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 340 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拼团商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_group_buy_activity_sku
-- ----------------------------

-- ----------------------------
-- Table structure for eb_group_buy_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_group_buy_record`;
CREATE TABLE `eb_group_buy_record`  (
  `group_buying_id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `group_activity_id` int NOT NULL COMMENT '拼团活动id',
  `product_group_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动商品ID',
  `skuid` int NOT NULL COMMENT '购买的商品 skuid',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `record_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=进行中，10=已成功，-1=已失败',
  `order_status` int NOT NULL DEFAULT 0 COMMENT '订单状态（0：待支付，1：待发货,2：部分发货， 3：待核销，4：待收货,5：已收货,6：已完成，9：已取消）',
  `ficti_status` int NOT NULL DEFAULT 0 COMMENT '虚拟成团状态0.未开启，1开启',
  `buying_count_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '成团总人数',
  `buying_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '真实人数',
  `yet_buying_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '已参团人数',
  `show_group` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '凑团 0不可见，1可见',
  `group_leader_uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '团长 用户ID ',
  `group_leader_nickname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '团长 昵称',
  `is_hidde` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否隐藏团信息 0 否 1 是',
  `is_del` int NOT NULL DEFAULT 0 COMMENT '删除标记',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  PRIMARY KEY (`group_buying_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拼团活动记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_group_buy_record
-- ----------------------------

-- ----------------------------
-- Table structure for eb_group_buy_user
-- ----------------------------
DROP TABLE IF EXISTS `eb_group_buy_user`;
CREATE TABLE `eb_group_buy_user`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id主键',
  `group_record_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '拼团记录ID',
  `product_group_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '活动商品ID',
  `group_activity_id` int NOT NULL DEFAULT 0 COMMENT '拼团活动id',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '购买的商品对应的商户id',
  `pay_num` int NOT NULL DEFAULT 0 COMMENT '购买数量',
  `order_status` int NOT NULL DEFAULT 0 COMMENT '订单状态（0：待支付，1：待发货,2：部分发货， 3：待核销，4：待收货,5：已收货,6：已完成，9：已取消）',
  `is_leader` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否为 团长 0=否 1=是',
  `order_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '订单ID 商户订单',
  `group_uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户ID ',
  `group_nickname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '昵称',
  `group_avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '头像',
  `is_del` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '删除标记',
  `record_status` int NOT NULL DEFAULT 0 COMMENT '状态：0=进行中，10=已成功，-1=已失败',
  `refund_status` int NOT NULL DEFAULT 0 COMMENT '退款状态：0 未退款 1 申请中 2 部分退款 3 已退款',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拼团参与成员表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_group_buy_user
-- ----------------------------

-- ----------------------------
-- Table structure for eb_group_config
-- ----------------------------
DROP TABLE IF EXISTS `eb_group_config`;
CREATE TABLE `eb_group_config`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `tag` int NOT NULL DEFAULT 0 COMMENT '标签:1-首页banner,2-首页推荐，3-经营理念，4-友情链接, 5-快捷入口，6-商户PC店铺Banner，7-商户PC店铺商品推荐，8-首页底部二维码，9-首页广告',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id,0-平台',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '名称',
  `link_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '链接地址',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片地址',
  `value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '值',
  `message` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '描述',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态:是否显示',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `expand` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拓展字段',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `name`(`name` ASC) USING BTREE,
  INDEX `tag`(`tag` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 77 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组合配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_group_config
-- ----------------------------

-- ----------------------------
-- Table structure for eb_marketing_activity
-- ----------------------------
DROP TABLE IF EXISTS `eb_marketing_activity`;
CREATE TABLE `eb_marketing_activity`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '活动ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '活动名称',
  `is_open` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否开启：0-未开启，1-已开启',
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '活动展示类型：1-轮播列表，2-大小格，3-大图模式',
  `sort` int NOT NULL DEFAULT 999 COMMENT '排序',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0未删除1已删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `banner` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动banner',
  `instruction` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '活动简介',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '营销活动表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_marketing_activity
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant`;
CREATE TABLE `eb_merchant`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '商户ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户名称',
  `category_id` int NOT NULL COMMENT '商户分类ID',
  `type_id` int NOT NULL COMMENT '商户类型ID',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户姓名',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户邮箱',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户手机号',
  `handling_fee` int NOT NULL COMMENT '手续费(%)',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户关键字',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '省',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '市',
  `district` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '区',
  `address_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户详细地址',
  `latitude` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '纬度',
  `longitude` varchar(25) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '经度',
  `is_self` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自营：0-自营，1-非自营',
  `is_recommend` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐:0-不推荐，1-推荐',
  `is_switch` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户开关:0-关闭，1-开启',
  `product_switch` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '商品审核开关:0-关闭，1-开启',
  `is_take_their` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '自提开关:0-关闭，1-开启',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `qualification_picture` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资质图片',
  `back_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户背景图',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户头像',
  `rectangle_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户logo（横）',
  `cover_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户封面图',
  `street_back_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户街背景图',
  `intro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户简介',
  `copy_product_num` int NOT NULL DEFAULT 0 COMMENT '复制商品数量',
  `balance` decimal(12, 2) NOT NULL DEFAULT 0.00 COMMENT '商户余额',
  `star_level` int NOT NULL DEFAULT 4 COMMENT '商户星级1-5',
  `pc_banner` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'pcBanner',
  `pc_back_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'pc背景图',
  `sort` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序',
  `create_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户创建类型：admin-管理员创建，apply-商户入驻申请',
  `create_id` int NOT NULL DEFAULT 0 COMMENT '创建商户管理员ID',
  `admin_id` int NOT NULL DEFAULT 0 COMMENT '关联管理账号ID',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `pc_logo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户PCLogo',
  `pc_good_store_cover_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户PC品牌好店封面图片',
  `receipt_printing_switch` int NULL DEFAULT 0 COMMENT '小票打印开关：0关闭，1=手动打印，2=自动打印，3=自动和手动',
  `is_force_shutdown` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户是否强制关闭:0-否，1-强制关闭',
  `electr_printing_switch` int NULL DEFAULT 0 COMMENT '电子面单开关：0关闭，1=开启',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_address
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_address`;
CREATE TABLE `eb_merchant_address`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户地址id',
  `mer_id` int UNSIGNED NOT NULL COMMENT '商户id',
  `receiver_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `receiver_phone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人电话',
  `province` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人所在省',
  `province_id` int NOT NULL DEFAULT 0 COMMENT '省份ID',
  `city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人所在市',
  `city_id` int NOT NULL DEFAULT 0 COMMENT '城市id',
  `district` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人所在区/县',
  `district_id` int NOT NULL DEFAULT 0 COMMENT '区/县id',
  `street` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人所在街道',
  `detail` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人详细地址',
  `post_code` int NOT NULL DEFAULT 0 COMMENT '邮编',
  `longitude` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '经度',
  `latitude` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '纬度',
  `is_default` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否默认',
  `is_show` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否开启',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `is_default`(`is_default` ASC) USING BTREE,
  INDEX `is_del`(`is_del` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户地址表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_address
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_apply
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_apply`;
CREATE TABLE `eb_merchant_apply`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '申请ID',
  `uid` int NOT NULL COMMENT '申请用户ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户名称',
  `category_id` int NOT NULL COMMENT '商户分类ID',
  `type_id` int NOT NULL COMMENT '商户类型ID',
  `account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户账号',
  `password` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '登录密码',
  `real_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户姓名',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户邮箱',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户手机号',
  `handling_fee` int NOT NULL COMMENT '手续费(%)',
  `keywords` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户关键字',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户地址',
  `is_self` tinyint UNSIGNED NOT NULL DEFAULT 1 COMMENT '是否自营：0-自营，1-非自营',
  `is_recommend` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否推荐:0-不推荐，1-推荐',
  `audit_status` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '审核状态：1-待审核，2-审核通过，3-审核拒绝',
  `denial_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `auditor_id` int NOT NULL DEFAULT 0 COMMENT '审核员ID',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `qualification_picture` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资质图片',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户申请表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_apply
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_balance_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_balance_record`;
CREATE TABLE `eb_merchant_balance_record`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录id',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '商户id',
  `link_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '关联单号（订单号、结算单号、退款单号）',
  `link_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '关联类型（order,closing,refund）',
  `type` int NOT NULL DEFAULT 1 COMMENT '类型：1-增加，2-扣减（提现）',
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题',
  `amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '金额',
  `balance` decimal(16, 2) NOT NULL DEFAULT 0.00 COMMENT '剩余',
  `mark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1-创建，2-冻结期，3-完成，4-失效（订单退款/申请被拒），5-结算申请',
  `frozen_time` int NOT NULL DEFAULT 0 COMMENT '冻结期时间（天）',
  `thaw_time` bigint NOT NULL DEFAULT 0 COMMENT '解冻时间',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `status`(`status` ASC) USING BTREE,
  INDEX `type`(`type` ASC) USING BTREE,
  INDEX `link_no`(`link_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户余额记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_balance_record
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_bill
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_bill`;
CREATE TABLE `eb_merchant_bill`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '帐单id',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类型：pay_order-订单支付,refund_order-订单退款,settlement-结算',
  `link_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '关联id',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关联单号',
  `uid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户uid,结算类型为0',
  `pm` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 = 支出 1 = 获得',
  `amount` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额',
  `mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `pm`(`pm` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户帐单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_bill
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_category
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_category`;
CREATE TABLE `eb_merchant_category`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '分类ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分类名称',
  `handling_fee` int NOT NULL COMMENT '手续费(%)',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户分类表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_category
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_closing_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_closing_record`;
CREATE TABLE `eb_merchant_closing_record`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `closing_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '结算单号',
  `amount` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '金额',
  `closing_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'bank' COMMENT '结算类型:bank-银行卡',
  `closing_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结算姓名',
  `closing_bank` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结算银行',
  `closing_bank_card` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结算银行卡号',
  `alipay_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付宝账号',
  `wechat_no` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信号',
  `payment_code` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收款二维码',
  `account_status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '到账状态：0-未到账，1-已到账',
  `closing_proof` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '结算凭证',
  `closing_time` timestamp NULL DEFAULT NULL COMMENT '结算时间',
  `audit_status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核状态：0-待审核，1-通过审核，2-审核失败',
  `refusal_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `audit_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核员id',
  `audit_time` timestamp NULL DEFAULT NULL COMMENT '审核时间',
  `mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户备注',
  `platform_mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商家结算记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_closing_record
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_daily_statement
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_daily_statement`;
CREATE TABLE `eb_merchant_daily_statement`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '帐单id',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `order_pay_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '订单支付总金额',
  `order_num` int NOT NULL DEFAULT 0 COMMENT '订单支付笔数',
  `order_income_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '订单收入金额',
  `handling_fee` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台手续费',
  `first_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '一级佣金金额',
  `second_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '二级佣金金额',
  `payout_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '支出总金额',
  `payout_num` int NOT NULL DEFAULT 0 COMMENT '支出笔数',
  `refund_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台退款金额',
  `refund_num` int NOT NULL DEFAULT 0 COMMENT '退款笔数',
  `income_expenditure` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '商户日收支',
  `data_date` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日期：年-月-日',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券补贴金额',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单积分抵扣金额',
  `order_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单实际退款金额',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券补贴金额',
  `refund_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还积分抵扣金额',
  `refund_handling_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还手续费金额',
  `brokerage_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '分佣',
  `refund_brokerage_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还佣金',
  `refund_merchant_transfer_amount` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还商户分账金额',
  `merchant_transfer_amount` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商户分账金额',
  `freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退运费金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `data_date`(`data_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户日帐单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_daily_statement
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_day_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_day_record`;
CREATE TABLE `eb_merchant_day_record`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日期，yyyy-MM-dd',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户id',
  `visitors` int NULL DEFAULT NULL COMMENT '访客量',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户日记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_day_record
