-- ----------------------------
-- Table structure for eb_merchant_delivery_personnel
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_delivery_personnel`;
CREATE TABLE `eb_merchant_delivery_personnel`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '商户ID',
  `personnel_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配送人员名称',
  `personnel_phone` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配送人员手机号',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态:1-开启，0-关闭',
  `is_delete` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户配送人员表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_delivery_personnel
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_elect
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_elect`;
CREATE TABLE `eb_merchant_elect`  (
  `op` int NULL DEFAULT NULL COMMENT '打印机类型0通用1快递100',
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户ID',
  `cloud_print_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '云打印机编号',
  `sender_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '寄件地址',
  `sender_username` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '寄件人',
  `sender_phone` varchar(11) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '寄件人电话',
  `update_time` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '商户电子面单配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of eb_merchant_elect
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_employee
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_employee`;
CREATE TABLE `eb_merchant_employee`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '头像',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `uid` int NOT NULL COMMENT '关联用户id',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '权限: 1订单管理，2商品管理，3售后管理，4代客下单，5订单核销，5统计',
  `creat_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` int NULL DEFAULT NULL COMMENT '状态：0关，1开',
  `mer_id` int NOT NULL COMMENT '关联的当前商户id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `id`(`id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户雇员表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_employee
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_express
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_express`;
CREATE TABLE `eb_merchant_express`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '商户id',
  `express_id` int NOT NULL DEFAULT 0 COMMENT '快递公司id',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递公司简称',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递公司全称',
  `partner_id` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要月结账号',
  `partner_key` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要月结密码',
  `net` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要取件网店',
  `account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '密码',
  `net_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '网点名称',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认',
  `is_open` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否开启',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户快递公司表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_express
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_info
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_info`;
CREATE TABLE `eb_merchant_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '商户信息ID',
  `mer_id` int NOT NULL COMMENT '商户ID',
  `settlement_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'bank' COMMENT '结算类型:bank-银行卡,wechat-微信,alipay-支付宝',
  `bank_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '持卡人姓名',
  `bank_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行名称',
  `bank_card` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '银行卡号',
  `bank_address` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '开户地址',
  `wechat_code` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信号',
  `wechat_qrcode_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '微信收款二维码',
  `alipay_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付宝账号',
  `alipay_qrcode_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '支付宝收款二维码',
  `alert_stock` int NOT NULL DEFAULT 0 COMMENT '警戒库存',
  `service_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服类型：H5-H5链接、phone-电话',
  `service_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服H5链接',
  `service_phone` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '客服电话',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `real_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_info
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_month_statement
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_month_statement`;
CREATE TABLE `eb_merchant_month_statement`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '帐单id',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户id',
  `order_pay_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '订单支付总金额',
  `order_num` int NOT NULL DEFAULT 0 COMMENT '订单支付笔数',
  `order_income_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '订单收入金额',
  `handling_fee` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台手续费',
  `first_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '一级佣金金额',
  `second_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '二级佣金金额',
  `payout_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '支出总金额',
  `payout_num` int NOT NULL DEFAULT 0 COMMENT '支出笔数',
  `refund_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台退款金额',
  `refund_num` int NOT NULL DEFAULT 0 COMMENT '退款笔数',
  `income_expenditure` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '商户月收支',
  `data_date` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日期：年-月',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券补贴金额',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单积分抵扣金额',
  `order_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单实际退款金额',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券补贴金额',
  `refund_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还积分抵扣金额',
  `refund_handling_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还手续费金额',
  `brokerage_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '分佣',
  `refund_brokerage_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还佣金',
  `merchant_transfer_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '商户分账金额',
  `refund_merchant_transfer_amount` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还商户分账金额',
  `freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退运费金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `data_date`(`data_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户月帐单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_month_statement
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_order
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_order`;
CREATE TABLE `eb_merchant_order`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `mer_id` int UNSIGNED NOT NULL COMMENT '商户ID',
  `uid` int UNSIGNED NOT NULL COMMENT '用户id',
  `real_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `user_phone` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人电话',
  `user_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货详细地址',
  `total_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品总数',
  `pro_total_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `total_postage` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '邮费',
  `total_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单总价',
  `pay_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际支付金额',
  `pay_postage` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '支付邮费',
  `use_integral` int NOT NULL DEFAULT 0 COMMENT '使用积分',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '积分抵扣金额',
  `coupon_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠券id',
  `coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `pay_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付方式:weixin,alipay,yue',
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付渠道：public-公众号,mini-小程序，h5-网页支付,yue-余额，wechatIos-微信Ios，wechatAndroid-微信Android,alipay-支付宝，alipayApp-支付宝App',
  `gain_integral` int NOT NULL DEFAULT 0 COMMENT '赠送积分',
  `user_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户备注',
  `merchant_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户备注',
  `shipping_type` tinyint NOT NULL DEFAULT 1 COMMENT '配送方式 1=快递 ，2=门店自提,3=虚拟发货',
  `first_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '一级返佣金额',
  `second_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '二级返佣金额',
  `commission_charge` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台手续费',
  `verify_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '核销码',
  `delivery_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'express' COMMENT '发货类型：express-快递,fictitious-虚拟发货,merchant-商家配送，noNeed-无需发货',
  `is_split_delivery` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否拆分发货',
  `seckill_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '秒杀商品ID 0-非砍价商品',
  `bargain_user_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '用户砍价活动id 0-没有',
  `bargain_id` int UNSIGNED NULL DEFAULT 0 COMMENT '砍价id 0-没有砍价',
  `pink_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '拼团id 0-没有拼团',
  `combination_id` int UNSIGNED NULL DEFAULT 0 COMMENT '拼团商品id 0-一般商品',
  `clerk_id` int NOT NULL DEFAULT 0 COMMENT '核销员id',
  `type` int NOT NULL DEFAULT 0 COMMENT '订单类型:0-基础订单,1-秒杀订单,2-拼团订单',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `mer_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商户优惠券金额',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券金额',
  `svip_discount_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT 'svip优惠金额',
  `is_svip` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否svip订单',
  `second_type` int NOT NULL DEFAULT 0 COMMENT '订单二级类型:0-普通订单，1-积分订单，2-虚拟订单，4-视频号订单，5-云盘订单，6-卡密订单',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_order
-- ----------------------------

-- ----------------------------
-- Table structure for eb_merchant_print
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_print`;
CREATE TABLE `eb_merchant_print`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户id',
  `print_type` int NULL DEFAULT NULL COMMENT '打印机类型: 0=易联云，1=飞蛾云',
  `print_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '易联云打印机名称',
  `print_yly_appid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '易联云appid',
  `print_yly_userid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '易联云用户id',
  `print_yly_sec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '易联云密钥',
  `print_yly_merchine_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '易联云终端号',
  `print_fe_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '飞蛾云打印机名称',
  `print_fe_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '飞蛾云打印机User',
  `print_fe_ukey` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '飞蛾云打印机UKey',
  `print_fe_sn` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '飞蛾云打印机SN',
  `status` int NULL DEFAULT NULL COMMENT '飞蛾云打印开关 0=关闭，1=开启',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打印内容',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户打印机表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_merchant_print
