-- ----------------------------
-- Table structure for eb_merchant_product_category
-- ----------------------------
DROP TABLE IF EXISTS `eb_merchant_product_category`;
CREATE TABLE `eb_merchant_product_category`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户Id',
  `pid` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '父级ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'icon',
  `sort` int NOT NULL DEFAULT 999 COMMENT '排序',
  `is_show` tinyint(1) NOT NULL DEFAULT 1 COMMENT '显示状态',
  `is_del` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户商品分类表' ROW_FORMAT = DYNAMIC;

