CREATE TABLE `eb_merchant_product_guarantee_group`  (
  `group_id` int NOT NULL COMMENT '组合id',
  `gid` int NOT NULL COMMENT '保障服务id',
  `is_show` tinyint(1) NOT NULL DEFAULT 1 COMMENT '显示状态',
  PRIMARY KEY (`group_id`, `gid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商户商品保障服务组合关联表' ROW_FORMAT = DYNAMIC;

