-- ----------------------------
-- Table structure for eb_order
-- ----------------------------
DROP TABLE IF EXISTS `eb_order`;
CREATE TABLE `eb_order`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户ID,商户订单等级有值',
  `uid` int UNSIGNED NOT NULL COMMENT '用户id',
  `total_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '订单商品总数',
  `pro_total_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品总价',
  `total_postage` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '邮费',
  `total_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单总价',
  `coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `use_integral` int NOT NULL DEFAULT 0 COMMENT '使用积分',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '积分抵扣金额',
  `pay_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际支付金额',
  `pay_postage` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '支付邮费',
  `paid` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '支付状态',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `pay_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付方式:weixin,alipay,yue',
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付渠道：public-公众号,mini-小程序，h5-网页支付,yue-余额，wechatIos-微信Ios，wechatAndroid-微信Android,alipay-支付宝，alipayApp-支付宝App',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '订单状态（0：待支付，1：待发货,2：部分发货， 3：待核销，4：待收货,5：已收货,6：已完成，9：已取消）',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '退款状态：0 未退款 1 申请中 2 部分退款 3 已退款',
  `cancel_status` tinyint NOT NULL DEFAULT 0 COMMENT '取消状态：0-未取消，1-系统取消，2-用户取消',
  `is_user_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '用户是否删除',
  `is_merchant_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '商户是否删除',
  `gain_integral` int NOT NULL DEFAULT 0 COMMENT '赠送积分',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户系统内部的订单号,32个字符内、可包含字母, 其他说明见商户订单号',
  `redirect` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付重定向地址',
  `type` int NOT NULL DEFAULT 0 COMMENT '订单类型:0-基础订单,1-秒杀订单,2-拼团订单',
  `level` int NOT NULL DEFAULT 0 COMMENT '订单等级:0-平台订单，1-商户订单',
  `plat_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台订单号',
  `is_del` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否删除',
  `receiving_time` timestamp NULL DEFAULT NULL COMMENT '收货时间',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `mer_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商户优惠券金额',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券金额',
  `plat_coupon_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '平台优惠券id',
  `svip_discount_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT 'svip优惠金额',
  `is_svip` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否svip订单',
  `second_type` int NOT NULL DEFAULT 0 COMMENT '订单二级类型:0-普通订单，1-积分订单，2-虚拟订单，4-视频号订单，5-云盘订单，6-卡密订单',
  `redeem_integral` int NOT NULL DEFAULT 0 COMMENT '兑换积分',
  `system_form_id` int NOT NULL DEFAULT 0 COMMENT '系统表单ID',
  `order_extend` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '系统表单数据',
  `group_buy_record_status` int NOT NULL DEFAULT 99 COMMENT '拼团订单状态：0=进行中，10=已成功，-1=已失败, 99=非拼团订单',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_order
-- ----------------------------

-- ----------------------------
-- Table structure for eb_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `eb_order_detail`;
CREATE TABLE `eb_order_detail`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `mer_id` int UNSIGNED NOT NULL COMMENT '商户ID',
  `uid` int UNSIGNED NOT NULL COMMENT '用户id',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `image` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `attr_value_id` int NOT NULL COMMENT '商品规格值 ID',
  `sku` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品sku',
  `price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '商品单价',
  `vip_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '会员价格',
  `pay_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '实际支付金额',
  `pay_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买数量',
  `weight` decimal(8, 2) UNSIGNED NOT NULL COMMENT '重量',
  `volume` decimal(8, 2) UNSIGNED NOT NULL COMMENT '体积',
  `is_reply` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否评价，0-未评价，1-已评价',
  `is_receipt` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否收货，0-未收货，1-已收货',
  `sub_brokerage_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '分佣类型:0-不参与分佣，1-单独分佣，2-默认分佣',
  `brokerage` int NOT NULL DEFAULT 0 COMMENT '一级返佣比例',
  `brokerage_two` int NOT NULL DEFAULT 0 COMMENT '二级返佣比例',
  `freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '优惠券金额',
  `use_integral` int NOT NULL DEFAULT 0 COMMENT '使用积分',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '积分抵扣金额',
  `gain_integral` int NOT NULL DEFAULT 0 COMMENT '赠送积分',
  `product_type` int NOT NULL DEFAULT 0 COMMENT '基础类型：0=普通商品,1-积分商品,2-虚拟商品,4=视频号,5-云盘商品,6-卡密商品',
  `first_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '一级返佣金额',
  `second_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '二级返佣金额',
  `delivery_num` int NOT NULL DEFAULT 0 COMMENT '发货数量',
  `apply_refund_num` int NOT NULL DEFAULT 0 COMMENT '申请退款数量',
  `refund_num` int NOT NULL DEFAULT 0 COMMENT '退款数量',
  `refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `refund_use_integral` int NOT NULL DEFAULT 0 COMMENT '退使用积分',
  `refund_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款积分抵扣金额',
  `refund_gain_integral` int NOT NULL DEFAULT 0 COMMENT '退赠送积分',
  `refund_first_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退一级返佣金额',
  `refund_second_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退二级返佣金额',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `mer_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商户优惠券金额',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券金额',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退运费金额',
  `expand` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拓展文本，例云盘链接',
  `card_secret_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡密ID字符串',
  `is_svip` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否svip订单',
  `is_paid_member_product` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否付费会员商品',
  `product_marketing_type` int NOT NULL DEFAULT 0 COMMENT '营销类型：0=基础商品,1=秒杀,2=拼团',
  `redeem_integral` int NOT NULL DEFAULT 0 COMMENT '兑换积分',
  `pro_refund_switch` tinyint(1) NOT NULL DEFAULT 1 COMMENT '商品是否支持退款',
  `group_buy_activity_id` int NOT NULL DEFAULT 0 COMMENT '拼团活动id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_order_detail
-- ----------------------------

-- ----------------------------
-- Table structure for eb_order_invoice
-- ----------------------------
DROP TABLE IF EXISTS `eb_order_invoice`;
CREATE TABLE `eb_order_invoice`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `mer_id` int UNSIGNED NOT NULL COMMENT '商户ID',
  `uid` int UNSIGNED NOT NULL COMMENT '用户id',
  `tracking_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '运单号',
  `express_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递名称',
  `express_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '快递公司简称',
  `total_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货商品总数',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `delivery_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'express' COMMENT '发货类型：express-快递,merchant-商家配送，noNeed-无需发货',
  `delivery_carrier` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '送货人姓名',
  `carrier_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '送货人手机号',
  `delivery_mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '发货备注',
  `express_record_type` int NULL DEFAULT 1 COMMENT '发货记录类型，1快递发货、2电子面单',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单发货单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_order_invoice
-- ----------------------------

-- ----------------------------
-- Table structure for eb_order_invoice_detail
-- ----------------------------
DROP TABLE IF EXISTS `eb_order_invoice_detail`;
CREATE TABLE `eb_order_invoice_detail`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `invoice_id` int UNSIGNED NOT NULL COMMENT '发货单ID',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `image` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `attr_value_id` int NOT NULL COMMENT '商品规格值 ID',
  `sku` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品sku',
  `num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '发货数量',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `invoice_id`(`invoice_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单发货单详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_order_invoice_detail
-- ----------------------------

-- ----------------------------
-- Table structure for eb_order_profit_sharing
-- ----------------------------
DROP TABLE IF EXISTS `eb_order_profit_sharing`;
CREATE TABLE `eb_order_profit_sharing`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '分账id',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号（商户）',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户ID',
  `order_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单付款金额',
  `integral_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '消耗积分数量',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单积分抵扣金额',
  `profit_sharing_plat_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台分账金额',
  `profit_sharing_mer_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商户分账金额',
  `first_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '一级返佣金额',
  `second_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '二级返佣金额',
  `profit_sharing_refund` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `refund_use_integral` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退还使用积分',
  `refund_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款积分抵扣金额',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券补贴金额',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券补贴金额',
  `refund_profit_sharing_plat_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台分账金额',
  `refund_profit_sharing_mer_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还商户分账金额',
  `refund_first_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还一级返佣金额',
  `refund_second_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还二级返佣金额',
  `freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还运费金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单分账表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_order_profit_sharing
-- ----------------------------

-- ----------------------------
-- Table structure for eb_order_status
-- ----------------------------
DROP TABLE IF EXISTS `eb_order_status`;
CREATE TABLE `eb_order_status`  (
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `change_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作类型:create-创建订单,pay-支付,express-快递,fictitious-虚拟发货,receipt-收货,evaluation-评价订单,fulfilled-完成,edit-编辑,cancel-取消,remove-删除订单',
  `change_message` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `change_type`(`change_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '订单操作记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_order_status
-- ----------------------------

-- ----------------------------
-- Table structure for eb_page_category
-- ----------------------------
DROP TABLE IF EXISTS `eb_page_category`;
CREATE TABLE `eb_page_category`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `pid` int NOT NULL DEFAULT 0 COMMENT '父类id',
  `type` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'link' COMMENT '类型:link、special、product、product_category、custom',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '分类名称',
  `sort` smallint NOT NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `level` tinyint(1) NOT NULL DEFAULT 0 COMMENT '层级',
  `is_mer` int NOT NULL DEFAULT 0 COMMENT '是否商户  0平台，商户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '页面链接分类' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_page_category
-- ----------------------------

-- ----------------------------
-- Table structure for eb_page_diy
-- ----------------------------
DROP TABLE IF EXISTS `eb_page_diy`;
CREATE TABLE `eb_page_diy`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `version` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '版本号',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '页面名称',
  `title` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '网站标题',
  `cover_image` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '封面图',
  `template_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '模板名称',
  `value` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '页面数据',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` int NOT NULL DEFAULT 0 COMMENT '是否使用',
  `type` int NOT NULL DEFAULT 0 COMMENT '页面类型',
  `is_show` int NOT NULL DEFAULT 0 COMMENT '显示首页',
  `is_bg_color` int NOT NULL DEFAULT 0 COMMENT '颜色是否选中',
  `is_bg_pic` int NOT NULL DEFAULT 0 COMMENT '背景图是否选中',
  `is_diy` int NOT NULL DEFAULT 0 COMMENT '是否是diy数据',
  `color_picker` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '背景颜色',
  `bg_pic` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '背景图',
  `bg_tab_val` int NOT NULL DEFAULT 0 COMMENT '背景图图片样式',
  `is_del` int NOT NULL DEFAULT 0 COMMENT '是否删除',
  `return_address` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '返回地址',
  `title_bg_color` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '1' COMMENT '标题背景色',
  `title_color` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '1' COMMENT '标题颜色',
  `service_status` int NOT NULL DEFAULT 1 COMMENT '商家样式',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '商户ID',
  `is_default` int NOT NULL DEFAULT 0 COMMENT '默认模板(1.平台默认 2.商户默认）',
  `text_position` int NOT NULL DEFAULT 0 COMMENT '标题文本位置',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `template_name`(`template_name` ASC, `type` ASC) USING BTREE,
  INDEX `status_type`(`status` ASC, `type` ASC) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 196 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = 'DIY数据表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_page_diy
-- ----------------------------

-- ----------------------------
-- Table structure for eb_page_link
-- ----------------------------
DROP TABLE IF EXISTS `eb_page_link`;
CREATE TABLE `eb_page_link`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `cate_id` int NOT NULL DEFAULT 0 COMMENT '分类id',
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '分组1:基础2:分销3:个人中心',
  `name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '页面名称',
  `url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '页面链接',
  `param` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '参数',
  `example` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '事例',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态',
  `sort` smallint NOT NULL DEFAULT 0 COMMENT '排序',
  `add_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `is_mer` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1是商户的链接',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '页面链接' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_page_link
-- ----------------------------

-- ----------------------------
-- Table structure for eb_paid_member_card
-- ----------------------------
DROP TABLE IF EXISTS `eb_paid_member_card`;
CREATE TABLE `eb_paid_member_card`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `label` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卡片标签',
  `type` int NOT NULL DEFAULT 0 COMMENT '0-试用，1-期限，2-永久',
  `deadline_day` int NOT NULL DEFAULT 0 COMMENT '期限天数',
  `original_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '会员卡原价',
  `price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '会员卡售价',
  `is_first_charge_give` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否仅首充赠送',
  `gift_balance` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '赠送余额',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：1-开启，0-关闭',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '付费会员卡表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_paid_member_card
-- ----------------------------

-- ----------------------------
-- Table structure for eb_paid_member_order
-- ----------------------------
DROP TABLE IF EXISTS `eb_paid_member_order`;
CREATE TABLE `eb_paid_member_order`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `uid` int NULL DEFAULT NULL COMMENT '用户UID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `card_id` int NULL DEFAULT NULL COMMENT '付费会员卡ID',
  `card_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `type` int NOT NULL DEFAULT 0 COMMENT '0-试用，1-期限，2-永久',
  `deadline_day` int NOT NULL DEFAULT 0 COMMENT '期限天数',
  `original_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '会员卡原价',
  `price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '会员卡售价',
  `gift_balance` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '赠送余额',
  `pay_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付方式:weixin,alipay,give,yue',
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付渠道：public-公众号,mini-小程序，h5-网页支付,wechatIos-微信Ios，wechatAndroid-微信Android,alipay-支付包，alipayApp-支付宝App,give-平台赠送,yue-余额支付',
  `paid` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否支付',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付服务方订单号',
  `card_expiration_time` datetime NULL DEFAULT NULL COMMENT '会员卡到期时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_wechat_shipping` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否微信小程序发货',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '付费会员订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_paid_member_order
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_brand
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_brand`;
CREATE TABLE `eb_pay_component_brand`  (
  `brand_id` int UNSIGNED NOT NULL COMMENT '品牌ID',
  `brand_wording` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '品牌名称',
  INDEX `brand_id`(`brand_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件品牌表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_brand
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_cat
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_cat`;
CREATE TABLE `eb_pay_component_cat`  (
  `third_cat_id` int UNSIGNED NOT NULL COMMENT '类目ID',
  `third_cat_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类目名称',
  `qualification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '类目资质',
  `qualification_type` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '类目资质类型,0:不需要,1:必填,2:选填',
  `product_qualification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品资质',
  `product_qualification_type` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品资质类型,0:不需要,1:必填,2:选填',
  `second_cat_id` int UNSIGNED NOT NULL COMMENT '二级类目ID',
  `second_cat_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '二级类目名称',
  `first_cat_id` int UNSIGNED NOT NULL COMMENT '一级类目ID',
  `first_cat_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '一级类目名称',
  `audit_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请id 有数据证明申请过',
  `status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT 'status  0初始化 1微信侧审核中 2微信侧审核失败 3微信侧审核成功',
  `audit_time` timestamp NULL DEFAULT NULL COMMENT '提审时间',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信侧审核拒绝原因',
  `audit_qualification_req` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '类目审核时提交的资质证明',
  INDEX `third_cat_id`(`third_cat_id` ASC) USING BTREE,
  INDEX `second_cat_id`(`second_cat_id` ASC) USING BTREE,
  INDEX `first_cat_id`(`first_cat_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2769 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件类目表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_cat
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_delivery_company
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_delivery_company`;
CREATE TABLE `eb_pay_component_delivery_company`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `delivery_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '快递公司id',
  `delivery_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '快递公司名称',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0未删除 1删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件快递公司表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_delivery_company
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_draft_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_draft_product`;
CREATE TABLE `eb_pay_component_draft_product`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '商品ID，商家自定义商品ID',
  `primary_product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '主商品ID',
  `component_product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '交易组件平台内部商品ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '绑定的小程序商品路径',
  `head_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '轮播图,多张',
  `qualification_pics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品资质图片,多张',
  `third_cat_id` int UNSIGNED NOT NULL COMMENT '第三级类目ID',
  `brand_id` int UNSIGNED NOT NULL COMMENT '品牌id',
  `info_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预留字段，用于版本控制',
  `status` int UNSIGNED NOT NULL COMMENT '微信侧状态:0-初始值，5-上架，11-自主下架，13-违规下架/风控系统下架',
  `edit_status` int UNSIGNED NOT NULL COMMENT '微信侧审核状态:1-未审核，2-审核中，3-审核失败，4-审核成功',
  `platform_status` int UNSIGNED NOT NULL COMMENT '平台状态:0初始值 5商家上架 6平台上架 11商家下架 12平台下架',
  `platform_edit_status` int UNSIGNED NOT NULL COMMENT '平台审核状态:1-未审核，2-平台审核中，3-平台审核失败，4-平台审核成功',
  `platform_status_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平台自定义状态审核原因',
  `reject_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '微信审核结果原因',
  `create_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `temp_id` int NOT NULL COMMENT '运费模板ID',
  `stock` int UNSIGNED NOT NULL COMMENT '库存',
  `sales` int UNSIGNED NOT NULL COMMENT '销量',
  `unit_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单位名称',
  `give_integral` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '反多少积分',
  `spec_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '规格 0单 1多',
  `ficti` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '虚拟销量',
  `desc_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'desc详情',
  `sku` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'sku',
  `attr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'attr(前端用)',
  `attr_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'attrValue(前端用)',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0未删除 1删除',
  `add_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商品草稿表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_draft_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_order
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_order`;
CREATE TABLE `eb_pay_component_order`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号,商家自定义订单ID',
  `component_order_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '微信侧订单id ',
  `openid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户的openid',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商家小程序该订单的页面path，用于微信侧订单中心跳转',
  `scene` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '下单时小程序的场景值',
  `out_user_id` int UNSIGNED NOT NULL COMMENT '用户id',
  `pay_method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支付方式，包括：微信支付,货到付款,其他',
  `pay_method_type` int UNSIGNED NOT NULL COMMENT '支付方式，0，微信支付，1: 货到付款，99: 其他（默认0）',
  `prepay_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'TODO 预支付ID',
  `prepay_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '预付款时间（拿到prepay_id的时间）',
  `order_price` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '该订单最终的金额（单位：分）',
  `freight` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '运费（单位：分）',
  `discounted_price` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '优惠金额（单位：分）',
  `additional_price` bigint UNSIGNED NOT NULL DEFAULT 0 COMMENT '附加金额（单位：分）',
  `additional_remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附加金额备注',
  `delivery_type` int UNSIGNED NOT NULL COMMENT '发货类型:1: 正常快递, 2: 无需快递, 3: 线下配送, 4: 用户自提 （默认1）',
  `receiver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收件人姓名',
  `detailed_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '详细收货地址信息',
  `tel_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收件人手机号码',
  `country` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '国家',
  `province` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省份',
  `city` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市',
  `town` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '乡镇',
  `ticket` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '拉起收银台的ticket 新版本中不需要这个参数',
  `ticket_expire_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT 'ticket有效截止时间 新版本不需要这个参数也就没有有效期了',
  `final_price` bigint UNSIGNED NOT NULL COMMENT '订单最终价格（单位：分）',
  `status` int UNSIGNED NOT NULL DEFAULT 10 COMMENT '订单状态：10-待付款，11-收银台支付完成（自动流转，对商家来说和10同等对待即可），20-待发货，30-待收货，100-完成，200-全部商品售后之后，订单取消，250-用户主动取消/待付款超时取消/商家取消',
  `finish_all_delivery` int UNSIGNED NULL DEFAULT NULL COMMENT '是否发货完成',
  `delivery_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '快递数组',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `transaction_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微信支付订单号',
  `time_end` timestamp NULL DEFAULT NULL COMMENT '订单支付时间，格式为yyyyMMddHHmmss',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_order
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_order_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_order_product`;
CREATE TABLE `eb_pay_component_order_product`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号,商家自定义订单ID',
  `component_order_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '微信侧订单id ',
  `product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '交易组件平台内部商品ID',
  `out_product_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商家自定义商品ID',
  `sku_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '交易组件平台内部skuID，可填0（如果这个product_id下没有sku）',
  `out_sku_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商家自定义商品skuID，可填空字符串（如果这个product_id下没有sku）',
  `product_cnt` int UNSIGNED NOT NULL COMMENT '购买的数量',
  `sale_price` bigint UNSIGNED NOT NULL COMMENT '生成这次订单时商品的售卖价（单位：分），可以跟上传商品接口的价格不一致',
  `head_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生成订单时商品的头图',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生成订单时商品的标题',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '绑定的小程序商品路径',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件订单详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_order_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_product`;
CREATE TABLE `eb_pay_component_product`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID，商家自定义商品ID',
  `primary_product_id` int UNSIGNED NOT NULL COMMENT '主商品ID',
  `component_product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '交易组件平台内部商品ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标题',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绑定的小程序商品路径',
  `head_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '轮播图,多张',
  `qualification_pics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品资质图片,多张',
  `third_cat_id` int UNSIGNED NOT NULL COMMENT '第三级类目ID',
  `brand_id` int UNSIGNED NOT NULL COMMENT '品牌id',
  `info_version` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '预留字段，用于版本控制',
  `status` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '微信侧状态:0-初始值，5-上架，11-自主下架，13-违规下架/风控系统下架',
  `edit_status` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '微信侧审核状态:1-未审核，2-审核中，3-审核失败，4-审核成功',
  `platform_status` int UNSIGNED NULL DEFAULT NULL COMMENT '平台状态:0初始值 5商家上架 6平台上架 11商家下架 12平台下架',
  `platform_edit_status` int UNSIGNED NULL DEFAULT NULL COMMENT '平台审核状态:1-未审核，2-平台审核中，3-平台审核失败，4-平台审核成功',
  `create_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新时间',
  `temp_id` int NULL DEFAULT NULL COMMENT '运费模板ID',
  `stock` int NOT NULL DEFAULT 0 COMMENT '库存',
  `sales` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `unit_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单位名称',
  `give_integral` int NOT NULL DEFAULT 0 COMMENT '反多少积分',
  `spec_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '规格 0单 1多',
  `ficti` int NOT NULL DEFAULT 0 COMMENT '虚拟销量',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0未删除 1删除',
  `is_sub` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否单独分佣',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_product_audit_info
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_product_audit_info`;
CREATE TABLE `eb_pay_component_product_audit_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_id` int UNSIGNED NOT NULL COMMENT '商品ID',
  `component_product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '交易组件平台内部商品ID',
  `submit_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上一次提交时间, yyyy-MM-dd HH:mm:ss',
  `audit_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上一次审核时间, yyyy-MM-dd HH:mm:ss',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '拒绝理由，只有edit_status为3时出现',
  `audit_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核单id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商品审核信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_product_audit_info
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_product_info
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_product_info`;
CREATE TABLE `eb_pay_component_product_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_id` int UNSIGNED NOT NULL COMMENT '商品ID',
  `component_product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '交易组件平台内部商品ID',
  `desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品详情',
  `imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品详情图片',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0未删除 1删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商品详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_product_info
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_product_sku
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_product_sku`;
CREATE TABLE `eb_pay_component_product_sku`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID，商家自定义skuID',
  `product_id` int UNSIGNED NOT NULL COMMENT '商品ID',
  `component_product_id` int UNSIGNED NULL DEFAULT NULL COMMENT '交易组件平台内部商品ID',
  `sku_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易组件平台自定义skuID',
  `thumb_img` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'sku小图',
  `sale_price` bigint UNSIGNED NOT NULL COMMENT '售卖价格,以分为单位',
  `market_price` bigint UNSIGNED NOT NULL COMMENT '市场价格,以分为单位',
  `stock_num` int UNSIGNED NOT NULL COMMENT '库存',
  `barcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '条形码',
  `sku_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品编码',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0未删除 1删除',
  `sku` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品属性索引值 (attr_value|attr_value[|....])',
  `attr_value_id` int UNSIGNED NULL DEFAULT NULL COMMENT '商品规格属性id',
  `version` int NULL DEFAULT 0 COMMENT '并发版本控制',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商品sku表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_product_sku
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_product_sku_attr
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_product_sku_attr`;
CREATE TABLE `eb_pay_component_product_sku_attr`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID，商家自定义skuID',
  `sku_id` int UNSIGNED NOT NULL COMMENT 'skuID',
  `component_sku_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交易组件平台自定义skuID',
  `attr_key` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售属性key（自定义）',
  `attr_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售属性value（自定义）',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除 0未删除 1删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `sku_id`(`sku_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商品sku属性表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_product_sku_attr
-- ----------------------------

-- ----------------------------
-- Table structure for eb_pay_component_shop_brand
-- ----------------------------
DROP TABLE IF EXISTS `eb_pay_component_shop_brand`;
CREATE TABLE `eb_pay_component_shop_brand`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `brand_id` int UNSIGNED NULL DEFAULT NULL COMMENT '品牌ID',
  `audit_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核单id',
  `license` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '营业执照或组织机构代码证，图片url/media_id,逗号分隔',
  `brand_audit_type` int UNSIGNED NULL DEFAULT NULL COMMENT '认证审核类型，1：国内品牌申请-R标，2：国内品牌申请-TM标，3：海外品牌申请-R标，4：海外品牌申请-TM标',
  `trademark_type` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标分类，共有45个分类',
  `brand_management_type` int UNSIGNED NULL DEFAULT NULL COMMENT '选择品牌经营类型：1-自有品牌，2-代理品牌，3-无品牌',
  `commodity_origin_type` int UNSIGNED NULL DEFAULT NULL COMMENT '商品产地是否进口：1-是，2-否',
  `brand_wording` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标/品牌词',
  `sale_authorization` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '销售授权书（如商持人为自然人，还需提供有其签名的身份证正反面扫描件)，图片url/media_id,逗号分隔',
  `trademark_registration_certificate` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商标注册证书，图片url/media_id,逗号分隔',
  `trademark_change_certificate` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商标变更证明，图片url/media_id,逗号分隔',
  `trademark_registrant` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标注册人姓名',
  `trademark_registrant_nu` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标注册号/申请号',
  `trademark_authorization_period` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标有效期，yyyy-MM-dd HH:mm:ss',
  `trademark_registration_application` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商标注册申请受理通知书，图片url/media_id,逗号分隔',
  `trademark_applicant` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标申请人姓名',
  `trademark_application_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商标申请时间, yyyy-MM-dd HH:mm:ss',
  `imported_goods_form` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '中华人民共和国海关进口货物报关单，图片url/media_id,逗号分隔',
  `status` int UNSIGNED NULL DEFAULT NULL COMMENT '审核状态, 0：审核中，1：审核成功，9：审核拒绝',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '如果审核拒绝，返回拒绝原因',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '组件商户品牌表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_pay_component_shop_brand
-- ----------------------------

-- ----------------------------
-- Table structure for eb_platform_daily_statement
-- ----------------------------
DROP TABLE IF EXISTS `eb_platform_daily_statement`;
CREATE TABLE `eb_platform_daily_statement`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '帐单id',
  `order_pay_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '订单支付总金额',
  `total_order_num` int NOT NULL DEFAULT 0 COMMENT '订单支付笔数',
  `handling_fee` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '日手续费收入',
  `merchant_transfer_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '商户分账金额',
  `merchant_transfer_num` int NOT NULL DEFAULT 0 COMMENT '商户分账笔数',
  `first_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '一级佣金金额',
  `second_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '二级佣金金额',
  `payout_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '支出总金额',
  `payout_num` int NOT NULL DEFAULT 0 COMMENT '支出笔数',
  `refund_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台退款金额',
  `refund_replace_brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台代扣佣金金额',
  `refund_num` int NOT NULL DEFAULT 0 COMMENT '退款笔数',
  `recharge_amount` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '充值金额',
  `recharge_num` int NOT NULL DEFAULT 0 COMMENT '充值笔数',
  `income_expenditure` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '平台日收支',
  `data_date` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日期：年-月-日',
  `refund_replace_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款平台积分抵扣金额',
  `integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单积分抵扣金额',
  `plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台优惠券补贴金额',
  `order_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '订单实际退款金额',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券补贴金额',
  `refund_handling_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还手续费金额',
  `brokerage_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '分佣',
  `refund_brokerage_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还佣金',
  `refund_merchant_transfer_amount` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还商户分账金额',
  `freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '运费金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退运费金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `data_date`(`data_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '平台日帐单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_platform_daily_statement
-- ----------------------------

