-- ----------------------------
-- Table structure for eb_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_product`;
CREATE TABLE `eb_product`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '商户Id',
  `image` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `flat_pattern` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '展示图',
  `slider_image` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '轮播图',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `intro` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品简介',
  `keyword` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关键字,英文逗号拼接',
  `cate_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户分类id(逗号拼接)',
  `brand_id` int NOT NULL DEFAULT 0 COMMENT '品牌id',
  `category_id` int NOT NULL DEFAULT 0 COMMENT '平台分类id',
  `guarantee_ids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '保障服务ids(英文逗号拼接)',
  `price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `vip_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '会员价格',
  `ot_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '市场价',
  `unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单位名',
  `sales` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '库存',
  `cost` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `ficti` int NULL DEFAULT 0 COMMENT '虚拟销量',
  `browse` int NULL DEFAULT 0 COMMENT '浏览量',
  `code_path` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品二维码地址(用户小程序海报)',
  `soure_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '淘宝京东1688类型',
  `video_link` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主图视频链接',
  `temp_id` int NOT NULL DEFAULT 1 COMMENT '运费模板ID',
  `sort` smallint NOT NULL DEFAULT 0 COMMENT '排序',
  `rank` smallint NOT NULL DEFAULT 0 COMMENT '总后台排序',
  `spec_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '规格 0单 1多',
  `is_recycle` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否回收站',
  `is_sub` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否单独分佣',
  `is_show` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0：未上架，1：上架）',
  `audit_status` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '审核状态：0-无需审核 1-待审核，2-审核成功，3-审核拒绝',
  `is_audit` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否加入审核，0-正常，1-审核流程中',
  `reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `type` int NOT NULL DEFAULT 0 COMMENT '基础类型：0=普通商品,1-积分商品,2-虚拟商品,4=视频号,5-云盘商品,6-卡密商品',
  `is_paid_member` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否付费会员商品',
  `is_auto_up` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否自动上架',
  `marketing_type` int NOT NULL DEFAULT 0 COMMENT '营销类型：0=基础商品,1=秒杀,2=拼团',
  `delivery_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '1' COMMENT '配送方式：1-商家配送，2-到店核销',
  `exchange_num` int NOT NULL DEFAULT 0 COMMENT '兑换数量',
  `is_hot` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否热门推荐',
  `redeem_integral` int NOT NULL DEFAULT 0 COMMENT '兑换积分',
  `refund_switch` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否支持退款',
  `system_form_id` int NOT NULL DEFAULT 0 COMMENT '系统表单ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `is_del`(`is_del` ASC) USING BTREE,
  INDEX `is_recycle`(`is_recycle` ASC) USING BTREE,
  INDEX `is_show`(`is_show` ASC) USING BTREE,
  INDEX `audit_status`(`audit_status` ASC) USING BTREE,
  INDEX `sort`(`sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_attr
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_attr`;
CREATE TABLE `eb_product_attr`  (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `attr_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '属性名',
  `attr_values` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '属性值，英文逗号拼接',
  `type` int NOT NULL DEFAULT 0 COMMENT '基础类型：0=普通商品,1-积分商品,2-虚拟商品,4=视频号,5-云盘商品,6-卡密商品',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除,0-否，1-是',
  `marketing_type` int NOT NULL DEFAULT 0 COMMENT '营销类型：0=基础商品,1=秒杀,2=拼团',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 551 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品属性表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_attr
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_attr_value
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_attr_value`;
CREATE TABLE `eb_product_attr_value`  (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` int UNSIGNED NOT NULL COMMENT '商品ID',
  `sku` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品属性sku',
  `stock` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '属性对应的库存',
  `sales` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '销量',
  `price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '价格',
  `image` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片',
  `cost` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '成本价',
  `bar_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品条码',
  `ot_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '原价',
  `weight` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '重量',
  `volume` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '体积',
  `brokerage` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '一级返佣',
  `brokerage_two` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '二级返佣',
  `type` int NOT NULL DEFAULT 0 COMMENT '基础类型：0=普通商品,1-积分商品,2-虚拟商品,4=视频号,5-云盘商品,6-卡密商品',
  `quota` int NULL DEFAULT NULL COMMENT '活动限购数量',
  `quota_show` int NULL DEFAULT NULL COMMENT '活动限购数量显示',
  `attr_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'attr_values 创建更新时的属性对应',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除,0-否，1-是',
  `version` int NULL DEFAULT 0 COMMENT '并发版本控制',
  `master_id` int NOT NULL DEFAULT 0 COMMENT '主商品attrValueID',
  `is_callback` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否回滚库存：0-未回滚，1-已回滚',
  `expand` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拓展文本，例云盘链接',
  `cdkey_id` int NOT NULL DEFAULT 0 COMMENT '卡密库ID',
  `vip_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '会员价格',
  `marketing_type` int NOT NULL DEFAULT 0 COMMENT '营销类型：0=基础商品,1=秒杀,2=拼团',
  `redeem_integral` int NOT NULL DEFAULT 0 COMMENT '兑换积分',
  `is_show` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否显示',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否默认',
  `item_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2818 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品属性值表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_product_attr_value
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_attribute
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_attribute`;
CREATE TABLE `eb_product_attribute`  (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `attribute_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规格名',
  `is_show_image` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否展示规格图片',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除,0-否，1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品规格表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_attribute
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_attribute_option
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_attribute_option`;
CREATE TABLE `eb_product_attribute_option`  (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `attribute_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品规格ID',
  `option_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '属性名',
  `image` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '图片',
  `sort` int NOT NULL DEFAULT 0 COMMENT '排序',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除,0-否，1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE,
  INDEX `attribute_id`(`attribute_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 88 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品规格属性表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_attribute_option
