-- ----------------------------
-- Table structure for eb_product_coupon
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_coupon`;
CREATE TABLE `eb_product_coupon`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL DEFAULT 0 COMMENT '商品id',
  `coupon_id` int NOT NULL DEFAULT 0 COMMENT '优惠劵id',
  `add_time` int NOT NULL DEFAULT 0 COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品优惠券表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_coupon
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_day_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_day_record`;
CREATE TABLE `eb_product_day_record`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日期，yyyy-MM-dd',
  `mer_id` int NULL DEFAULT NULL COMMENT '商户id',
  `product_id` int NULL DEFAULT NULL COMMENT '商品id',
  `page_view` int NULL DEFAULT NULL COMMENT '浏览量',
  `collect_num` int NULL DEFAULT NULL COMMENT '收藏量',
  `add_cart_num` int NULL DEFAULT NULL COMMENT '加购件数',
  `order_product_num` int NULL DEFAULT NULL COMMENT '下单商品数（销售件数）',
  `order_success_product_fee` decimal(8, 2) NULL DEFAULT NULL COMMENT '销售额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品日记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_product_day_record
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_description
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_description`;
CREATE TABLE `eb_product_description`  (
  `product_id` int NOT NULL DEFAULT 0 COMMENT '商品ID',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品详情',
  `type` int NOT NULL DEFAULT 0 COMMENT '基础类型：0=普通商品,1-积分商品,2-虚拟商品,4=视频号,5-云盘商品,6-卡密商品',
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `marketing_type` int NOT NULL DEFAULT 0 COMMENT '营销类型：0=基础商品,1=秒杀,2=拼团',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `product_id`(`product_id` ASC, `type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 504 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品描述表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_description
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_guarantee
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_guarantee`;
CREATE TABLE `eb_product_guarantee`  (
