-- Records of eb_product_guarantee_group
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_relation
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_relation`;
CREATE TABLE `eb_product_relation`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `uid` int UNSIGNED NOT NULL COMMENT '用户ID',
  `product_id` int UNSIGNED NOT NULL COMMENT '商品ID',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联类型(收藏(collect）、点赞(like))',
  `category` int NOT NULL DEFAULT 0 COMMENT '商品类型：0=普通商品，1=秒杀，2=砍价，3=拼团, 4=视频号, 5-云盘商品,6-卡密商品',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品点赞和收藏表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_product_relation
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_reply
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_reply`;
CREATE TABLE `eb_product_reply`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `uid` int NOT NULL DEFAULT 0 COMMENT '用户ID',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '店铺id',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单编号',
  `order_detail_id` int NOT NULL DEFAULT 0 COMMENT '订单详情id',
  `product_id` int NOT NULL COMMENT '商品id',
  `attr_value_id` int NOT NULL COMMENT '商品规格属性id',
  `sku` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品规格属性值,多个,号隔开',
  `star` tinyint(1) NOT NULL DEFAULT 5 COMMENT '星级',
  `comment` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '评论内容',
  `pics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评论图片',
  `merchant_reply_content` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '管理员回复内容',
  `merchant_reply_time` timestamp NULL DEFAULT NULL COMMENT '管理员回复时间',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '0未删除1已删除',
  `is_reply` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0未回复1已回复',
  `nickname` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户名称',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户头像',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `order_detail_id`(`order_detail_id` ASC) USING BTREE,
  INDEX `product_id`(`product_id` ASC) USING BTREE,
  INDEX `star`(`star` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '评论表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_reply
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_rule
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_rule`;
CREATE TABLE `eb_product_rule`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '店铺id，平台为0',
  `rule_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规格名称',
  `rule_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '规格值',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品规则值(规格)表' ROW_FORMAT = COMPACT;

-- ----------------------------
-- Records of eb_product_rule
-- ----------------------------

-- ----------------------------
-- Table structure for eb_product_tag
-- ----------------------------
DROP TABLE IF EXISTS `eb_product_tag`;
CREATE TABLE `eb_product_tag`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tag_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签名称',
  `tag_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签说明',
  `sort` int NOT NULL COMMENT '排序',
  `status` int NULL DEFAULT 0 COMMENT '状态#0关闭|1开启',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `position` int NOT NULL COMMENT '标签在商城中的位置#0=标题下|1=标题前',
  `play_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品参与类型 product=指定商品，brand=指定品牌，merchant=指定商户，category=指定商品分类',
  `play_products` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '参与的规则id集合，配合play_type使用,在内置标签情况下这里是配置的规则值',
  `owner` int NULL DEFAULT 1 COMMENT '归属方#0=系统内置(不能删除)|1=平台自建',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品标签表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_product_tag
-- ----------------------------

-- ----------------------------
-- Table structure for eb_recharge_order
-- ----------------------------
DROP TABLE IF EXISTS `eb_recharge_order`;
CREATE TABLE `eb_recharge_order`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `uid` int NULL DEFAULT NULL COMMENT '充值用户UID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '充值金额',
  `give_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '购买赠送金额',
  `pay_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付方式:weixin,alipay',
  `pay_channel` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付渠道：public-公众号,mini-小程序，h5-网页支付,wechatIos-微信Ios，wechatAndroid-微信Android,alipay-支付包，alipayApp-支付宝App',
  `paid` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否支付',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '充值支付时间',
  `out_trade_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '支付服务方订单号',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '充值时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_wechat_shipping` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否上传微信发货管理',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE,
  INDEX `pay_type`(`pay_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '充值订单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_recharge_order
-- ----------------------------

-- ----------------------------
-- Table structure for eb_refund_order
-- ----------------------------
DROP TABLE IF EXISTS `eb_refund_order`;
CREATE TABLE `eb_refund_order`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `refund_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退款订单号',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商户订单号',
  `mer_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商户ID',
  `uid` int UNSIGNED NOT NULL COMMENT '用户id',
  `real_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人姓名',
  `user_phone` varchar(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人电话',
  `user_address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收货人详细地址',
  `total_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退款单商品总数',
  `refund_reason_wap` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款原因',
  `refund_reason_wap_img` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款图片',
  `refund_reason_wap_explain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款用户说明',
  `is_all` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否整单退款',
  `refund_status` tinyint NOT NULL DEFAULT 0 COMMENT '售后状态：0:待审核 1:商家拒绝 2：退款中 3:已退款 4:用户退货 5:商家待收货 6:已撤销',
  `refund_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝退款说明',
  `refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `merchant_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商家退款金额',
  `platform_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台退款金额',
  `refund_first_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退一级返佣金额',
  `refund_second_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退二级返佣金额',
  `is_replace` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否平台代扣佣金',
  `refund_use_integral` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退还使用积分',
  `refund_gain_integral` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扣除赠送积分',
  `refund_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款积分抵扣金额',
  `refund_time` timestamp NULL DEFAULT NULL COMMENT '退款时间',
  `refund_pay_type` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '退款渠道类型:weixin,alipay,yue',
  `mer_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商户备注',
  `platform_remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '平台备注',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券补贴金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退运费金额',
  `after_sales_type` int NOT NULL DEFAULT 1 COMMENT '售后类型：1-仅退款，2-退货退款',
  `return_goods_type` int NOT NULL DEFAULT 0 COMMENT '退货类型：0-不退货 1-快递退回，2-到店退货',
  `receiver` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `receiver_phone` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人电话',
  `receiver_address_detail` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '收货人详细地址',
  `express_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `tracking_number` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '运单号',
  `telephone` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户联系电话',
  `is_compulsory_refund` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否强制退款',
  `compulsory_admin_id` int NOT NULL DEFAULT 0 COMMENT '强制操作账户ID',
  `is_user_revoke` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否用户撤销',
  `promoter_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'user' COMMENT '退款发起方：user-用户，merchant-商户',
  `out_refund_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '第三方退款订单号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `refund_order_no`(`refund_order_no` ASC) USING BTREE,
  INDEX `mer_id`(`mer_id` ASC) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退款单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_refund_order
-- ----------------------------

-- ----------------------------
-- Table structure for eb_refund_order_info
-- ----------------------------
DROP TABLE IF EXISTS `eb_refund_order_info`;
CREATE TABLE `eb_refund_order_info`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `refund_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '退款订单号',
  `mer_id` int UNSIGNED NOT NULL COMMENT '商户ID',
  `order_detail_id` int UNSIGNED NOT NULL COMMENT '订单商品表ID',
  `product_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '商品ID',
  `product_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `image` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品图片',
  `attr_value_id` int NOT NULL COMMENT '商品规格值 ID',
  `sku` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品sku',
  `price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '商品单价',
  `pay_price` decimal(8, 2) UNSIGNED NOT NULL COMMENT '支付金额',
  `pay_num` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '购买数量',
  `product_type` int NOT NULL DEFAULT 0 COMMENT '商品类型:0-普通，1-秒杀，2-砍价，3-拼团，4-视频号',
  `apply_refund_num` int UNSIGNED NOT NULL COMMENT '申请退款数量',
  `refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款金额',
  `merchant_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '商家退款金额',
  `platform_refund_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '平台退款金额',
  `refund_use_integral` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '退还使用积分',
  `refund_integral_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退款积分抵扣金额',
  `refund_gain_integral` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '扣除赠送积分',
  `refund_first_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退一级返佣金额',
  `refund_second_brokerage_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退二级返佣金额',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `refund_plat_coupon_price` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退还平台优惠券补贴金额',
  `refund_freight_fee` decimal(8, 2) UNSIGNED NOT NULL DEFAULT 0.00 COMMENT '退运费金额',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `refund_order_no`(`refund_order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退款订单详情表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_refund_order_info
-- ----------------------------

-- ----------------------------
-- Table structure for eb_refund_order_status
-- ----------------------------
DROP TABLE IF EXISTS `eb_refund_order_status`;
CREATE TABLE `eb_refund_order_status`  (
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单号',
  `change_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作类型：apply-申请退款，audit-商家审核，returning-商品退回，receiving-商家确认收货，refund-退款，compulsory-平台强制退款，revoke-撤销',
  `change_message` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  INDEX `order_no`(`order_no` ASC) USING BTREE,
  INDEX `change_type`(`change_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退款订单操作记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_refund_order_status
-- ----------------------------

-- ----------------------------
-- Table structure for eb_schedule_job
-- ----------------------------
DROP TABLE IF EXISTS `eb_schedule_job`;
CREATE TABLE `eb_schedule_job`  (
  `job_id` int NOT NULL AUTO_INCREMENT COMMENT '任务id',
  `bean_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'spring bean名称',
  `method_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方法名',
  `params` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参数',
  `cron_expression` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'cron表达式',
  `status` tinyint NULL DEFAULT NULL COMMENT '任务状态  0：正常  1：暂停',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint UNSIGNED NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`job_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定时任务' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_schedule_job
-- ----------------------------

-- ----------------------------
-- Table structure for eb_schedule_job_log
-- ----------------------------
DROP TABLE IF EXISTS `eb_schedule_job_log`;
CREATE TABLE `eb_schedule_job_log`  (
  `log_id` int NOT NULL AUTO_INCREMENT COMMENT '任务日志id',
  `job_id` int NOT NULL COMMENT '任务id',
  `bean_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'spring bean名称',
  `method_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '方法名',
  `params` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参数',
  `status` tinyint NOT NULL COMMENT '任务状态    1：成功    0：失败',
  `error` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '失败信息',
  `times` int NOT NULL COMMENT '耗时(单位：毫秒)',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`log_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定时任务日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_schedule_job_log
-- ----------------------------

-- ----------------------------
-- Table structure for eb_seckill_activity
-- ----------------------------
DROP TABLE IF EXISTS `eb_seckill_activity`;
CREATE TABLE `eb_seckill_activity`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '秒杀活动ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '秒杀活动名称',
  `start_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '秒杀开始日期',
  `end_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '秒杀结束日期',
  `one_quota` int NOT NULL DEFAULT 0 COMMENT '活动期间单笔下单购买数量，0不限制',
  `all_quota` int NOT NULL DEFAULT 0 COMMENT '全部活动期间，用户购买总数限制，0不限制',
  `mer_stars` int NOT NULL DEFAULT 0 COMMENT '商家星级',
  `pro_category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '商品类型,英文逗号拼接',
  `is_open` int NOT NULL DEFAULT 0 COMMENT '开启状态: 0=关闭 1=开启',
  `status` int NOT NULL DEFAULT 0 COMMENT '状态:0未开始，1进行中，2已结束',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标记 0=未删除 1=删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀活动表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_seckill_activity
-- ----------------------------

-- ----------------------------
-- Table structure for eb_seckill_activity_time
-- ----------------------------
DROP TABLE IF EXISTS `eb_seckill_activity_time`;
CREATE TABLE `eb_seckill_activity_time`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `seckill_id` int NOT NULL COMMENT '秒杀id',
  `time_interval_id` int NOT NULL COMMENT '秒杀时段id',
  `start_date` int NOT NULL COMMENT '秒杀开始日期',
  `end_date` int NOT NULL COMMENT '秒杀结束日期',
  `start_time` int NOT NULL COMMENT '秒杀开启时间',
  `end_time` int NOT NULL COMMENT '秒杀结束时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `sekill_id`(`seckill_id` ASC) USING BTREE,
  INDEX `time_interval_id`(`time_interval_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 234 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀活动时间表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_seckill_activity_time
-- ----------------------------

-- ----------------------------
-- Table structure for eb_seckill_product
-- ----------------------------
DROP TABLE IF EXISTS `eb_seckill_product`;
CREATE TABLE `eb_seckill_product`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '秒杀商品ID',
  `activity_id` int NOT NULL COMMENT '活动id',
  `product_id` int NOT NULL COMMENT '商品id',
  `mer_id` int NOT NULL DEFAULT 0 COMMENT '商户Id',
  `image` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品图片',
  `flat_pattern` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '展示图',
  `slider_image` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '轮播图',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品名称',
  `intro` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '商品简介',
  `keyword` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '关键字,英文逗号拼接',
  `brand_id` int NOT NULL DEFAULT 0 COMMENT '品牌id',
  `category_id` int NOT NULL DEFAULT 0 COMMENT '平台分类id',
  `guarantee_ids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '保障服务ids(英文逗号拼接)',
  `price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `seckill_price` decimal(8, 2) NOT NULL DEFAULT 0.00 COMMENT '商品价格',
  `unit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单位名',
  `sales` int NOT NULL DEFAULT 0 COMMENT '销量',
  `temp_id` int NOT NULL DEFAULT 1 COMMENT '运费模板ID',
  `sort` smallint NOT NULL DEFAULT 0 COMMENT '排序',
  `spec_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '规格 0单 1多',
  `is_show` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态（0：未上架，1：上架）',
  `audit_status` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '审核状态：1-待审核，2-审核成功，3-审核拒绝',
  `reason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '拒绝原因',
  `quota_show` int NOT NULL DEFAULT 0 COMMENT '限购总数显示.不变',
  `quota` int NOT NULL DEFAULT 0 COMMENT '限购总数,随减',
  `is_del` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `type` int NOT NULL DEFAULT 0 COMMENT '基础类型：0=普通商品,1-积分商品,2-虚拟商品,4=视频号,5-云盘商品,6-卡密商品',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `is_del`(`is_del` ASC) USING BTREE,
  INDEX `sort`(`sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀商品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_seckill_product
-- ----------------------------

-- ----------------------------
-- Table structure for eb_seckill_time_interval
-- ----------------------------
DROP TABLE IF EXISTS `eb_seckill_time_interval`;
CREATE TABLE `eb_seckill_time_interval`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '秒杀时段名称',
  `start_time` int NOT NULL COMMENT '秒杀时段开始时间',
  `end_time` int NOT NULL COMMENT '秒杀时段结束时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=关闭 1=开启',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标记 0=未删除 1=删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '秒杀时段表' ROW_FORMAT = DYNAMIC;

