-- Table structure for eb_user_sign_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_user_sign_record`;
CREATE TABLE `eb_user_sign_record`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `uid` int NOT NULL DEFAULT 0 COMMENT '用户id',
  `integral` int NOT NULL DEFAULT 0 COMMENT '签到积分',
  `experience` int NOT NULL DEFAULT 0 COMMENT '签到经验',
  `day` int NOT NULL DEFAULT 1 COMMENT '连续签到天数',
  `award_integral` int NOT NULL DEFAULT 0 COMMENT '连续签到奖励积分',
  `award_experience` int NOT NULL DEFAULT 0 COMMENT '连续签奖励到经验',
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '签到日期，yyyy-MM-dd',
  `mark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注说明',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid`(`uid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户签到记录表' ROW_FORMAT = DYNAMIC;

