-- Table structure for eb_user_visit_record
-- ----------------------------
DROP TABLE IF EXISTS `eb_user_visit_record`;
CREATE TABLE `eb_user_visit_record`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '记录id',
  `uid` int NOT NULL DEFAULT 0 COMMENT '用户uid',
  `visit_type` int NOT NULL DEFAULT 1 COMMENT '访问类型 1-首页，2-详情页，3-营销活动详情页，4-个人中心',
  `num` int NOT NULL DEFAULT 1 COMMENT '访问数量',
  `date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '日期',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date` ASC) USING BTREE,
  INDEX `visit_type`(`visit_type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户访问记录表' ROW_FORMAT = DYNAMIC;

