INSERT INTO `eb_pay_component_cat` VALUES (1116, '瓜果类', '1、国产商品：四选一①《农作物种子生产经营许可证》②《林木种子生产经营许可证》④《种子的备案登记》和授权人的《种子生产经营许可证》（若备案登记中不包含种子的目录，还须提供授权人授权的《种子的目录》） 2、进口商品需提供：①《种子经营许可证》；②进口商的进出口贸易资格证；③《出入境检验检疫证明》或《出入境检验检疫卫生证书》；④供货协议或采购合同等材料。 （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 1, '', 0, 1115, '种子', 1069, '农资园艺', NULL, 0, NULL, NULL, '');
