INSERT INTO `eb_pay_component_cat` VALUES (1210, '处方狗粮', '1、营业执照（且经营许可范围内包含对应经营类目如：宠物食品及用品零售）； 2、国产商品需提供：①《饲料生产许可证》；②供货协议或采购合同等材料； 3、进口商品需提供：①《进口饲料登记证》；②《出入境检验检疫证明》或《出入境检验检疫卫生证书》；③近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名④供货协议或采购合同等材料。 （注：若申请主体为生产商或是办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 1, '', 0, 1209, '宠物主粮', 1208, '宠物生活', NULL, 0, NULL, NULL, '');
