INSERT INTO `eb_pay_component_cat` VALUES (1493, '灭鼠药', '1、国产商品需提供：申请主体的《农药经营许可证》或《农药生产许可证》。 2、进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料。 （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 1, '根据相关法律法规及平台运营规则，经营此类商品需提供《农药登记证》（如无法提供证件，可提供产品外包装照片，需显示登记证号）', 1, 1492, '驱蚊驱虫', 1453, '家庭清洁/纸品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (1494, '驱蚊/蝇/小强/蚁类药', '售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料。 （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '根据相关法律法规及平台运营规则，经营此类商品需提供《农药登记证》（如无法提供证件，可提供产品外包装照片，需显示登记证号且为WP开头）', 1, 1492, '驱蚊驱虫', 1453, '家庭清洁/纸品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (1497, '其它健康电器', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 1496, '个护健康', 1495, '家用电器', NULL, 0, NULL, NULL, '');
