INSERT INTO `eb_pay_component_cat` VALUES (6019, '智能手表', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '1、若产品可插卡通讯需要提供①《电信设备进网许可证》，可前往全国认证认可信息公共服务平台查询；②《国家强制性产品认证证书》（CCC安全认证证书），可前往全国认证认可信息公共服务平台查询；③《无线电发射设备核准认证》，可前往全国认证认可信息公共服务平台查询。 2、若产品不可插卡通讯需要提供《无线电发射设备核准认证》，可前往全国认证认可信息公共服务平台查询。', 1, 6011, '智能设备', 1972, '数码', NULL, 0, NULL, NULL, '');
