INSERT INTO `eb_pay_component_cat` VALUES (112880, '世界军事', '需提供申请主体的《出版物经营许可证》；（注：经营主体若为分公司可提供总公司的《出版物经营许可证》和当地出版管理机关（新闻出版局）的备案回执）', 1, '1、书籍的ISBN版号/CN刊号 2、清晰可辨认的出版社信息 （仅限出版社为大陆出版社的书籍）', 1, 376698, '军事/政治', 135835, '图书', NULL, 0, NULL, NULL, '');
