INSERT INTO `eb_pay_component_cat` VALUES (377082, '美甲', '1、营业执照（且经营许可范围内包含对应经营类目）； 2、公共场所卫生许可证； 3、门店照片（含门店门头、内景照片）。', 1, '', 0, 377079, '丽人', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377091, '家政保洁', '《营业执照》经营范围包含家政服务等相关项目', 1, '1、服务内容标准化，商品必须完整描述服务名称，具体包含的服务内容，商品详情须明确描述有效期，使用注意事项等内容； 2、服务内容若包含高空清洗服务还需提供《高空清洗悬吊作业企业安全生产证书》； 3、提供服务的商家需与小商店主体一致。', 2, 377101, '家政', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377102, '家电维修', '《营业执照》经营范围包含家政服务等相关项目', 1, '1、服务内容标准化，商品必须完整描述服务名称，具体包含的服务内容，商品详情须明确描述有效期，使用注意事项等内容； 2、提供服务的商家需与小商店主体一致。', 2, 377101, '家政', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377104, '安装服务', '需提供：1、住建部颁发的工程设计与施工资质相应等级证书（主要含室内装修、装饰范围）；2、各级建设厅颁发的相应的建筑业企业资质证书；3、经营装修施工需拥有3个（含）以上实体门店，上传门店的门头照片； 注：营业执照：加载“统一社会信用代码”的营业执照，经营整体全包、整体半包需公司注册满2年，注册资金200万（含）以上，其他类目需公司注册满2年，注册资金100万（含）以上。', 1, '', 0, 377103, '装修服务', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377105, '装修监理', '需提供：1、住建部颁发的工程设计与施工资质相应等级证书（主要含室内装修、装饰范围）；2、各级建设厅颁发的相应的建筑业企业资质证书；3、工程监理需提供建设部或中国室内装饰协会（含地区性装饰协会）颁发的工程监理资质证书； 注：营业执照：加载“统一社会信用代码”的营业执照且公司注册满2年，注册资金100万（含）以上。', 1, '', 0, 377103, '装修服务', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377106, '装修设计', '需提供（2选1）： 1、各级装饰协会颁发的室内装饰企业资质等级证书等证明文件； 2、提供五套设计案例，每套设计案例需包含以下四项资质：①案例家具平面布置图、地面铺装图、顶面设计图；②至少三张不同空间的效果图；③完工案例实景照片至少五张；④案例基础信息：项目地址、户型、面积、造价、项目介绍（风格、思路、灵感等）（word格式）。 注：营业执照：加载“统一社会信用代码”的营业执照且需公司注册满2年，注册资金100万（含）以上。', 1, '', 0, 377103, '装修服务', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377107, '养生', '需提供申请主体的《出版物经营许可证》；（注：经营主体若为分公司可提供总公司的《出版物经营许可证》和当地出版管理机关（新闻出版局）的备案回执）', 1, '1、书籍的ISBN版号/CN刊号 2、清晰可辨认的出版社信息 （仅限出版社为大陆出版社的书籍）', 1, 122146, '健身与保健', 135835, '图书', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377108, '国学普及读物', '需提供申请主体的《出版物经营许可证》；（注：经营主体若为分公司可提供总公司的《出版物经营许可证》和当地出版管理机关（新闻出版局）的备案回执）', 1, '1、书籍的ISBN版号/CN刊号 2、清晰可辨认的出版社信息 （仅限出版社为大陆出版社的书籍）', 1, 128191, '国学/古籍', 135835, '图书', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377109, '经典著作', '需提供申请主体的《出版物经营许可证》；（注：经营主体若为分公司可提供总公司的《出版物经营许可证》和当地出版管理机关（新闻出版局）的备案回执）', 1, '1、书籍的ISBN版号/CN刊号 2、清晰可辨认的出版社信息 （仅限出版社为大陆出版社的书籍）', 1, 117803, '管理', 135835, '图书', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377110, '旅游指南', '需提供申请主体的《出版物经营许可证》；（注：经营主体若为分公司可提供总公司的《出版物经营许可证》和当地出版管理机关（新闻出版局）的备案回执）', 1, '1、书籍的ISBN版号/CN刊号 2、清晰可辨认的出版社信息 （仅限出版社为大陆出版社的书籍）', 1, 112871, '旅游/地图', 135835, '图书', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (377111, '农业基础科学', '需提供申请主体的《出版物经营许可证》；（注：经营主体若为分公司可提供总公司的《出版物经营许可证》和当地出版管理机关（新闻出版局）的备案回执）', 1, '1、书籍的ISBN版号/CN刊号 2、清晰可辨认的出版社信息 （仅限出版社为大陆出版社的书籍）', 1, 135836, '农业/林业', 135835, '图书', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (378006, '公职考试培训', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍。 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、若涉及学历、技能证书，需提供2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 380003, '学历资格/职业技能培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (378007, '教师资格培训', '1、线下授课：提供申请主体的人力资源社会保障部门批准的文件或《民办学校办学许可证》 2、线上授课：①需提供申请主体的《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》；②提供申请主体的人力资源社会保障部门批准的文件或《民办学校办学许可证》。', 1, '', 0, 380003, '学历资格/职业技能培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (378008, '其他学历/资格考试', '1、线下授课：提供申请主体的人力资源社会保障部门批准的文件或《民办学校办学许可证》 2、线上授课：①需提供申请主体的《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》；②提供申请主体的人力资源社会保障部门批准的文件或《民办学校办学许可证》。', 1, '', 0, 380003, '学历资格/职业技能培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
