INSERT INTO `eb_pay_component_cat` VALUES (378043, '健骨补钙', '1、营业执照经营范围：许可项目包含至少一项【兽药经营，饲料/添加剂销售，宠物食品及用品零售，宠物服务（不含动物诊疗）】； 2、兽药经营企业须提供《兽药经营许可证》，饲料/添加剂销售企业需提供生产厂商的《饲料生产许可证》 、《饲料添加剂生产许可证》； 3、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）；②《出入境检验检疫证明》或《出入境检验检疫卫生证书》（检疫证明或卫生证书需与报关单的合同协议号一致、且报关单应展现对应品牌名称及商品名称）； 4、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 378042, '宠物保健', 1208, '宠物生活', NULL, 0, NULL, NULL, '');
