INSERT INTO `eb_pay_component_cat` VALUES (435001, '律师服务', '1、营业执照（且经营许可范围内包含法律咨询等相关项目）；2、仅向依法设立的法律服务机构开放，请提供申请主体的《律师事务所执业许可证》或经司法厅批准成立法律服务机构的文件', 1, '', 0, 429004, '法律服务', 377078, '生活服务', NULL, 0, NULL, NULL, '');
