INSERT INTO `eb_pay_component_cat` VALUES (435006, '诊治服务 ', '需提供申请主体的《营业执照》（经营范围包括动物诊疗等）和《动物诊疗许可证》', 1, '', 0, 422005, '宠物医疗', 1208, '宠物生活', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (436003, '音乐/舞蹈/戏曲演出 ', '1、演出举办单位需提供：《营业性演出许可证》。2、代理方需提供：持演出举办单位提供的授权文件+举办方的《营业性演出许可证》', 1, '', 0, 428007, '本地玩乐', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (436004, '航空兑换卡', '需提供申请主体的《营业执照》、《商标注册证》和《公共航空运输企业经营许可证》', 1, '', 0, 436002, '会员卡券', 429008, '其他', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (441001, '协会会费', '', 0, '', 0, 423003, '生活缴费', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (441002, '义卖商品', '需提供[《慈善组织登记证书》](https://developers.weixin.qq.com/doc/ministore/minishopspecification/zizhizhengzhao/zizhi/cishandj/cishandj.html)或[《慈善组织公开募捐资质证书》](https://developers.weixin.qq.com/doc/ministore/minishopspecification/zizhizhengzhao/zizhi/cishanmj/cishanmj.html)或提供由登记地所在地的民政部门认定为慈善组织的文件证明材料', 1, '', 0, 436001, '公益', 442005, '公益服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (441003, '文艺修养', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 378005, '生活兴趣', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (441004, '家长教育', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 383005, '青少年素质教育', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (441006, '预付卡', '需提供：1、申请主体的发卡方单用途预付卡备案的证明文件； 2、发卡企业向备案机关提交的包含该入驻商家（售卡单位）的售卡企业清单及承诺函（入驻商家为发卡方无需提供此项）。', 1, '', 0, 436002, '会员卡券', 429008, '其他', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (441008, '优惠券', '', 0, '', 0, 431009, '团购促销', 429008, '其他', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (442002, '美容养颜', '1、需提供《食品经营许可证》（经营项目包含保健食品销售）或《食品生产许可证》（食品类别包含保健食品）； （注：自贸区企业若无法提供《食品经营许可证》，需提供营业执照（经营范围需包含保健食品销售））； 2、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 3、经营进口商品需提供：①近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议；②入境货物检验检疫证明：经营进口商品，需提供与报关单合同协议号一致的检验检疫证明。 ', 1, '需提供1、《国产保健食品批准证书》或《进口保健食品批准证书》； 2、产品中文标签、中文说明书； 3、委托加工协议：产品标签中存在委托生产关系的，需提供品牌商和生产商的委托加工协议，另附产品清单。', 1, 378089, '保健食品', 7419, '食品饮料', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (442003, '葛根', '1、国产商品需提供：申请主体的《食品经营许可证》或《食品生产许可证》或《预包装食品销售备案凭证》。 2、进口商品需提供：①申请主体的《食品经营许可证》或《预包装食品销售备案凭证》；②近一年内的《出入境检验检疫证明》或《出入境检验检疫卫生证书》；③供货协议或采购合同等材料。 （注：①若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料；②自贸区企业若无法提供《食品经营许可证》，需要提供营业执照（经营范围需包含食品经营（预包装食品）））', 1, '1、若经营单一的且未经炮制、加工的中药材类初级农产品须符合以下要求： ①商品外包装须符合《农产品包装和标识管理办法》的规定，应当在包装物上标注或者附加标识标明品名、产地、生产者或者销售者名称、生产日期;②需在商品详情处自我声明不属于中药饮片，不得替代中药饮片作临床调剂和中成药原料使用 2、产品中文标签、中文说明书 3、委托加工协议：产品标签中存在委托生产关系的，需提供品牌商和生产商的委托加工协议，另附产品清单 4、农产品地理标志登记证书：标记产地的农产品需提供《农产品地理标志登记证书》', 2, 378091, '传统滋补', 7419, '食品饮料', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (442004, '桑葚', '1、国产商品需提供：申请主体的《食品经营许可证》或《食品生产许可证》或《预包装食品销售备案凭证》。 2、进口商品需提供：①申请主体的《食品经营许可证》或《预包装食品销售备案凭证》；②近一年内的《出入境检验检疫证明》或《出入境检验检疫卫生证书》；③供货协议或采购合同等材料。 （注：①若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料；②自贸区企业若无法提供《食品经营许可证》，需要提供营业执照（经营范围需包含食品经营（预包装食品）））', 1, '1、若经营单一的且未经炮制、加工的中药材类初级农产品须符合以下要求： ①商品外包装须符合《农产品包装和标识管理办法》的规定，应当在包装物上标注或者附加标识标明品名、产地、生产者或者销售者名称、生产日期;②需在商品详情处自我声明不属于中药饮片，不得替代中药饮片作临床调剂和中成药原料使用 2、产品中文标签、中文说明书 3、委托加工协议：产品标签中存在委托生产关系的，需提供品牌商和生产商的委托加工协议，另附产品清单 4、农产品地理标志登记证书：标记产地的农产品需提供《农产品地理标志登记证书》', 2, 378091, '传统滋补', 7419, '食品饮料', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (442008, '局部装修', '需提供：1、住建部颁发的工程设计与施工资质相应等级证书（主要含室内装修、装饰范围）；2、各级建设厅颁发的相应的建筑业企业资质证书；3、经营装修施工需拥有3个（含）以上实体门店，上传门店的门头照片； 注：营业执照：加载“统一社会信用代码”的营业执照，经营整体全包、整体半包需公司注册满2年，注册资金200万（含）以上，其他类目需公司注册满2年，注册资金100万（含）以上。', 1, '', 0, 377103, '装修服务', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (454001, '境内游学 ', '需提供申请主体的《旅行社业务经营许可证》', 1, '', 0, 378005, '生活兴趣', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (454002, '餐饮', '需提供申请主体的《食品经营许可证》、《食品流通许可证》、《小餐饮登记》（任一）或其他同等效力证件', 1, '', 0, 527035, '餐饮', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (468002, '预约服务', '1、需提供申请主体的《营业执照》（需包含家具经营范围）；2、请上传线下门店照片', 1, '（选填） 请说明预约服务具体规则，并在商品详情中标注（规则需明确到店后，如不产生消费，不增收费用）', 2, 1363, '定制家具', 1247, '家具', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (469001, '预约服务', '1、如主体为房产开发商需提供《营业执照》（经营范围需包含房地产开发）； 2、如主体为房产中介机构需提供《营业执照》（经营范围需包含房地产中介/经济服务）', 1, '1.房产开发商需提供所展示楼盘的《商品房预售许可证》或《商品房销售许可证》（主体名应与证件主体一致）； 2.房产中介需提供当地政府的备案公示 ；3.商品为预约服务类型，请说明具体规则。', 1, 468001, '房地产', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (477001, '汽车试驾', '1、如主体为汽车厂商需提供《营业执照》和《工信部道路机动车辆生产企业准入许可》； 2、如主体为汽车经销商/4s店需提供《营业执照》和《厂商授权销售文件》与《工信部道路机动车辆生产企业准入许可》； 3、如主体为下属子/分公司需提供《营业执照》、《工信部道路机动车辆生产企业准入许可》与《股权关系证明函》（含双方盖章）； 注：需提供线下门店照片', 1, '（选填）请说明试驾具体规则，并在商品详情中标注（规则需明确仅试驾不增收其他费用）', 2, 378068, '汽车服务', 6263, '汽车', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (480001, '权益券', '1、如主体为房地产开发商：①需提供《营业执照》（经营范围需包含房地产开发）；②房地产开发资质等级证书或房地产开发企业暂定资质证书； 2、如主体为非房地产开发商：①需提供与开发商之间的合作协议（如：授权书）；②开发商的房地产开发资质等级证书或房地产开发企业暂定资质证书；③开发商的《营业执照》（经营范围需包含房地产开发）', 1, '1、如主体为房地产开发商需要在商品详情处展示楼盘的《商品房预售许可证》或《商品房销售许可证》； 2、如主体非房地产开发商①需要提供与开发商之间的合作协议（如：授权书）；②需要在商品详情展处示对应合作楼盘的《商品房预售许可证》或《商品房销售许可证》', 1, 468001, '房地产', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (494001, '预约报名', '', 0, '（选填）商品为预约服务类型，请说明试驾具体规则', 2, 378068, '汽车服务', 6263, '汽车', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (494003, '岫岩玉', '需提供1款由国/省/市级质监局或同级别检测机构出具的完整的相关质检/检测报告。报告需包含：① CMA或CNAS标识；② 商标/商品图、检测单位、商品成分各含量鉴定结论', 1, '', 0, 378215, '其它玉石', 378136, '珠宝首饰', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (494028, '加油服务', '行业运营商主体： ①需提供申请主体的《成品油零售经营批准证书》;②发卡方单用途预付卡备案的证明文件。 代理经销商主体： ①需提供与油企品牌直接签署的协议;②发卡方单用途预付卡备案的证明文件；', 1, '', 0, 527036, '加油服务', 530004, '出行与交通', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (494033, '暖宝宝', '', 0, '', 0, 1046, '身体护理', 1001, '个人护理', NULL, 0, NULL, NULL, '');
