INSERT INTO `eb_pay_component_cat` VALUES (494036, '体测仪', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (494037, '户外电源', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7117, '户外装备', 6932, '运动户外', NULL, 0, NULL, NULL, '');
