INSERT INTO `eb_pay_component_cat` VALUES (502040, '素颜霜', '1、如主体为生产商，售卖国内商品需提供：①《化妆品生产许可证》； 2、如主体为进口商，售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料； （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 6911, '香水彩妆', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502041, '弹力棒/健身棒', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502042, '健身椅', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502044, '菌/菇/酵素', '需提供： 1、 《食品经营许可证》或《预包装食品销售备案凭证》。 2、① 报关单：需提供近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若报关单上的经营使用单位或收货单位不在授权链上，需同时提供委托进口协议）；② 入境货物检验检疫证明：需提供与报关单合同协议号一致的检验检疫证明。', 1, '1、2选1：①  需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明产品可以普通食品身份进入市场。② 《进口保健食品批准证书》 2、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。', 1, 530056, '海外膳食营养补充食品', 502043, '膳食营养补充食品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502045, '植物精华/提取物', '需提供： 1、 《食品经营许可证》或《预包装食品销售备案凭证》。 2、① 报关单：需提供近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若报关单上的经营使用单位或收货单位不在授权链上，需同时提供委托进口协议）；② 入境货物检验检疫证明：需提供与报关单合同协议号一致的检验检疫证明。', 1, '1、2选1：①  需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明产品可以普通食品身份进入市场。② 《进口保健食品批准证书》 2、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。', 1, 530056, '海外膳食营养补充食品', 502043, '膳食营养补充食品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502046, '烹饪烘焙小吃餐饮培训', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍。 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、若涉及学历、技能证书，需提供2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 380003, '学历资格/职业技能培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502047, '财务/会计培训', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 380003, '学历资格/职业技能培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502048, '法语', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 517051, '语言培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502049, '少儿体育培训', '1、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》加营业执照（经营范围中应包含“教育培训”），或《民办非企业单位法人证书》。②《事业单位法人证书》（适用公立学校）； 2、 线下授课需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 530065, '本地教育培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (502050, '蹦床', '1、 《营业执照》。 2、 《娱乐场所经营许可证》。', 1, '', 0, 428007, '本地玩乐', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (508001, '国内旅游', '1、旅行社总社需提供：①《旅行社业务经营许可证》；②旅行社责任险保险单 。 2、旅行社分社需提供：①旅行社分社备案登记证明； ②旅行社责任险保险单（若为总社统一购买提供总社旅行社责任险保险单）；③总社的《旅行社业务经营许可证》； ④旅行社分社和总社补充协议（如：由总社出具的知情同意责任书）。 3、旅行社若经营“境外一日游/多日游”“潜水”、“境外玩乐套餐”、“接送（机场/点对点/拼车）”类目，除提供上述资质外，还须提供至少一份与实际服务提供方的有效合作协议', 1, '', 0, 525002, '旅游度假', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (510023, '唐装/中式服装', '', 0, '', 0, 6057, '女装', 6033, '服饰内衣', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (510025, '按摩膏/磨砂膏', '售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料。 （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 1046, '身体护理', 1001, '个人护理', NULL, 0, NULL, NULL, '');
