INSERT INTO `eb_pay_component_cat` VALUES (517005, '宽带新装', '运营商主体：需提供《基础电信业务经营许可证》 非运营商主体：①提供与市级以上移动运营商（电信/联通需提供省级以上）的代理合同或合作协议等正规渠道证明②提供合作协议对应运营商授权认证的《网络销售与实名制授权书》③提供合作协议对应运营商统一配发的授权防伪二维码标识④最近6个月在对应省份的宽带竣工订单数量数据表且加盖运营商部门章，或运营商出具的宽带竣工订单数量证明函', 1, '', 0, 1966, '通信服务', 377078, '生活服务', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (517035, '男士精油', '1、如主体为生产商，售卖国内商品需提供：①《化妆品生产许可证》； 2、如主体为进口商，售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料； （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 6871, '男士面部护肤', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (517036, '男士鼻贴', '1、如主体为生产商，售卖国内商品需提供：①《化妆品生产许可证》； 2、如主体为进口商，售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料； （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 6871, '男士面部护肤', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (517039, '呼啦圈', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (517040, '计步器', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (517041, '健身球/保健球', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (517042, '扭腰盘', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
