INSERT INTO `eb_pay_component_cat` VALUES (524041, '笔译服务', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍。 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、若涉及学历、技能证书，需提供2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 380003, '学历资格/职业技能培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (524042, '其他语种', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 517051, '语言培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (524043, '代金券', '需提供《网络预约出租汽车经营许可证》或《营业执照》（经营范围包含“票务代理”）。', 1, '', 0, 496042, '票务', 530004, '出行与交通', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (524044, '黑头仪', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 524026, '个护仪器', 1001, '个人护理', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525032, '定妆喷雾', '1、如主体为生产商，售卖国内商品需提供：①《化妆品生产许可证》； 2、如主体为进口商，售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料； （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 6911, '香水彩妆', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525033, '身体乳/油', '售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料。 （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 1046, '身体护理', 1001, '个人护理', NULL, 0, NULL, NULL, '');
