INSERT INTO `eb_pay_component_cat` VALUES (525037, '防晒衣', '', 0, '', 0, 526028, '童装户外服饰', 6153, '母婴', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525038, '软壳衣/软壳裤', '', 0, '', 0, 526028, '童装户外服饰', 6153, '母婴', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525039, '发育内衣/抹胸', '', 0, '', 0, 494030, '童装内衣裤', 6153, '母婴', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525040, '佛跳墙', '1、国产商品需提供：申请主体的《食品经营许可证》或《食品生产许可证》或《预包装食品销售备案凭证》。 2、进口商品需提供：①申请主体的《食品经营许可证》或《预包装食品销售备案凭证》；②近一年内的《出入境检验检疫证明》或《出入境检验检疫卫生证书》；③供货协议或采购合同等材料。 （注：①若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料；②自贸区企业若无法提供《食品经营许可证》，需要提供营业执照（经营范围需包含食品经营（预包装食品）））', 1, '（选填）若经营清真食品，需提供生产厂商的《清真食品生产经营许可证》或相关证件', 2, 527038, '半成品菜/方便菜', 6625, '生鲜', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525041, '其他膳食营养补充食品', '需提供： 1、 《食品经营许可证》或《预包装食品销售备案凭证》。 2、① 报关单：需提供近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若报关单上的经营使用单位或收货单位不在授权链上，需同时提供委托进口协议）；② 入境货物检验检疫证明：需提供与报关单合同协议号一致的检验检疫证明。', 1, '1、2选1：①  需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明产品可以普通食品身份进入市场。② 《进口保健食品批准证书》 2、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。', 1, 530056, '海外膳食营养补充食品', 502043, '膳食营养补充食品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525042, '膳食纤维/碳水化合物', '需提供： 《食品经营许可证》或《食品生产许可证》或《预包装食品销售备案凭证》；注：自贸区企业若无法提供《食品经营许可证》，需要提供营业执照（经营范围需包含食品经营（预包装食品））', 1, '1、请提供商品外包装中文标签图，标签图需包含执行标准、食品生产许可证编号、配料表等关键信息。 2、3选1：①  若商品为企业标准生产的，需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明商品可以以普通食品身份进入市场。②若商品为国家标准生产的, 需提供与商品标签对应一致的、近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告。③若商品为保健食品需要提供 《国产保健食品批准证书》。 3、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。', 1, 521044, '普通膳食营养补充食品', 502043, '膳食营养补充食品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525043, '脂肪酸/脂类', '需提供： 《食品经营许可证》或《食品生产许可证》或《预包装食品销售备案凭证》；注：自贸区企业若无法提供《食品经营许可证》，需要提供营业执照（经营范围需包含食品经营（预包装食品））', 1, '1、请提供商品外包装中文标签图，标签图需包含执行标准、食品生产许可证编号、配料表等关键信息。 2、3选1：①  若商品为企业标准生产的，需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明商品可以以普通食品身份进入市场。②若商品为国家标准生产的, 需提供与商品标签对应一致的、近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告。③若商品为保健食品需要提供 《国产保健食品批准证书》。 3、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。', 1, 521044, '普通膳食营养补充食品', 502043, '膳食营养补充食品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525044, '植物精华/提取物', '需提供： 《食品经营许可证》或《食品生产许可证》或《预包装食品销售备案凭证》；注：自贸区企业若无法提供《食品经营许可证》，需要提供营业执照（经营范围需包含食品经营（预包装食品））', 1, '1、请提供商品外包装中文标签图，标签图需包含执行标准、食品生产许可证编号、配料表等关键信息。 2、3选1：①  若商品为企业标准生产的，需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明商品可以以普通食品身份进入市场。②若商品为国家标准生产的, 需提供与商品标签对应一致的、近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告。③若商品为保健食品需要提供 《国产保健食品批准证书》。 3、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。', 1, 521044, '普通膳食营养补充食品', 502043, '膳食营养补充食品', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525045, '日语', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 517051, '语言培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525046, '恋爱技巧', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 510037, '情感心理', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525047, '婚姻经营', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 510037, '情感心理', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525048, '喷雾补水仪', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '根据相关法律法规及平台运营规则，请上传《国家强制性产品认证证书》（CCC安全认证证书）', 2, 524026, '个护仪器', 1001, '个人护理', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (525049, '综合健身', '《营业执照》（经营范围包含运动类、健身等相关项目）', 1, '如涉及到游泳项目，需提供《高危险性体育项目经营许可证》。', 2, 428007, '本地玩乐', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526001, '快车', '需提供申请主体的《网络预约出租汽车经营许可证》', 1, '', 0, 521002, '打车（网约车）', 530004, '出行与交通', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526002, '出租车', '需提供（2选1）： 1、出租车公司：《道路运输经营许可证》；  2、出租车平台：与出租车公司合作协议 以及合作出租车公司的《道路运输经营许可证》', 1, '', 0, 510002, '出租车', 530004, '出行与交通', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526005, '高段位奶粉', '1、国产商品需提供（4选1）1.《食品经营许可证》；2.《食品生产许可证》；3. ①《营业执照》【经营范围需含“仅销售预包装食品”和“婴幼儿配方乳粉/其他婴幼儿配方食品”】； ②《预包装食品销售备案凭证》（若当地未下发备案凭证，请提供证明材料）； 4.《营业执照》【经营范围需含“仅销售预包装食品”和“婴幼儿配方乳粉/其他婴幼儿配方食品”】（仅自由贸易试验区适用）； 2、若售卖进口商品，除上述（4选1）外还需补充提供：①近一年内的《出入境检验检疫证明》 或《出入境检验检疫卫生证书》；②近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '1、商品标题需说明奶粉适用范围、婴幼儿奶粉需注明奶粉段位或适用年龄段。 2、婴幼儿配方奶粉需提供《婴幼儿配方乳粉注册证书》； 3、特殊食品需提供：①特殊食品的注册/备案文件（文件中应包含标签、说明书的内容）；②产品实物的标签、说明书。', 2, 378056, '奶粉', 6153, '母婴', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526031, '喷雾', '1、如主体为生产商，售卖国内商品需提供：①《化妆品生产许可证》； 2、如主体为进口商，售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料； （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 6896, '面部护肤', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526033, '修容/阴影', '1、如主体为生产商，售卖国内商品需提供：①《化妆品生产许可证》； 2、如主体为进口商，售卖进口商品需提供：①《出入境检验检疫证明》或《出入境检验检疫卫生证书》；②供货协议或采购合同等材料； （注：若申请主体为办理出入境检验证的收货人，则无需提供供货协议或采购合同等材料）', 2, '国产：国产非特殊用途化妆品备案（网上备案的电子凭证）或者国产特殊用途化妆品卫生许可批件； 进口：进口非特殊用途化妆品备案（网上备案的电子凭证）或者进口特殊用途化妆品卫生许可批件。', 1, 6911, '香水彩妆', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
