INSERT INTO `eb_pay_component_cat` VALUES (526040, '俄语', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。 3、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》；加营业执照（经营范围中应包含“教育培训”）或《民办非企业单位法人证书》，②《事业单位法人证书》（适用公立学校）。', 1, '', 0, 517051, '语言培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526041, '创业知识', '1、 需填写《产品经营说明书》注明线上/线下授课，主营类目及主推产品介绍 2、①如提供线上教育服务，需提供《增值电信业务许可证》，核准业务种类含“信息服务业务（仅限互联网信息服务）\"或《ICP备案》（若ICP备案资质主办单位名称非申请主体，需加盖主办单位红色公章，或提交关系证明/签署协议）；②如线下授课，需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 530064, '创业理财', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526042, '成人语言线下培训', '1、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》加营业执照（经营范围中应包含“教育培训”），或《民办非企业单位法人证书》。②《事业单位法人证书》（适用公立学校）； 2、 线下授课需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 530065, '本地教育培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526043, '少儿才艺', '1、2选1：① 区、县级教育部门颁发的《民办学校办学许可证》加营业执照（经营范围中应包含“教育培训”），或《民办非企业单位法人证书》。②《事业单位法人证书》（适用公立学校）； 2、 线下授课需提供线下门店照及门店场地证明（场地和校舍产权证明或合法规范的租赁协议书）。', 1, '', 0, 530065, '本地教育培训', 381003, '教育培训', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (526044, '滑雪场', '1、 《营业执照》（经营范围包含运动类、健身等相关项目）。 2、 《高危险性体育项目经营许可证》。', 1, '', 0, 428007, '本地玩乐', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (527001, '出境旅游', '1、旅行社总社需提供：①《旅行社业务经营许可证》；②旅行社责任险保险单 。 2、旅行社分社需提供：①旅行社分社备案登记证明； ②旅行社责任险保险单（若为总社统一购买提供总社旅行社责任险保险单）；③总社的《旅行社业务经营许可证》； ④旅行社分社和总社补充协议（如：由总社出具的知情同意责任书）。 3、旅行社若经营“境外一日游/多日游”“潜水”、“境外玩乐套餐”、“接送（机场/点对点/拼车）”类目，除提供上述资质外，还须提供至少一份与实际服务提供方的有效合作协议', 1, '', 0, 525002, '旅游度假', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (527002, '周边/当地游', '1、旅行社总社需提供：①《旅行社业务经营许可证》；②旅行社责任险保险单 。 2、旅行社分社需提供：①旅行社分社备案登记证明； ②旅行社责任险保险单（若为总社统一购买提供总社旅行社责任险保险单）；③总社的《旅行社业务经营许可证》； ④旅行社分社和总社补充协议（如：由总社出具的知情同意责任书）。 3、旅行社若经营“境外一日游/多日游”“潜水”、“境外玩乐套餐”、“接送（机场/点对点/拼车）”类目，除提供上述资质外，还须提供至少一份与实际服务提供方的有效合作协议', 1, '', 0, 525002, '旅游度假', 128209, '旅游休闲', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (527041, '假睫毛辅助工具', '', 0, '', 0, 6885, '美妆工具', 6870, '美妆护肤', NULL, 0, NULL, NULL, '');
INSERT INTO `eb_pay_component_cat` VALUES (527042, '漫步机', '1、质检报告：提供近一年内由第三方权威质检机构出具的含有CMA或CNAS认证的质检报告； 2、经营进口商品的，需提供①近一年内的中华人民共和国海关进口货物报关单（报关单应展现对应品牌名称及商品名称）； 3、若申请主体不是报关单的经营使用单位或收货单位，需同时提供委托进口协议。', 1, '', 0, 7060, '健身训练', 6932, '运动户外', NULL, 0, NULL, NULL, '');
